import {useAlive} from '@github-ui/use-alive'
import {useCallback, useRef} from 'react'

import {useFileSyncerContext} from '../contexts/FileSyncerContext'

// when a push event occurrs on the repo, don't sync if we've synced in the last few seconds to avoid infiinite loops.
const DELAY_SYNC_REPOSITORY_EVENTS = 2 * 1000

type RepositoryNotificationHandlerProps = {
  channel: string
}

export function RepositoryNotificationHandler({channel}: RepositoryNotificationHandlerProps) {
  const lastRepositoryEventAt = useRef<number | undefined>(undefined)
  const {getFileSyncerV2, forceContentRefresh, forceFileTreeRefresh} = useFileSyncerContext()

  const syncRepository = useCallback(async () => {
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) {
      return
    }
    // use lastCommitEvent at to avoid syncing if the last commit was made recently
    if (lastRepositoryEventAt.current && Date.now() - lastRepositoryEventAt.current < DELAY_SYNC_REPOSITORY_EVENTS) {
      return
    }
    lastRepositoryEventAt.current = Date.now()
    const synced = await fileSyncer.syncRepository()
    if (synced) {
      forceContentRefresh()
      forceFileTreeRefresh()
    }
  }, [forceContentRefresh, forceFileTreeRefresh, getFileSyncerV2])

  useAlive(channel, syncRepository)

  return null
}

try{ RepositoryNotificationHandler.displayName ||= 'RepositoryNotificationHandler' } catch {}