import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {useViewport} from '@github-ui/use-viewport'
import {useGlobalReadOnly} from '@github-ui/workbench/contexts/WorkbenchStoreContext'
import type {Workbench} from '@github-ui/workbench/types/workbench-types'
import {workbenchDeployUrl} from '@github-ui/workbench/utilities/urls'
import {LinkExternalIcon, RepoIcon, SparkleFillIcon, StarFillIcon, StarIcon, TrashIcon} from '@primer/octicons-react'
import {ActionList, IconButton, Label, RelativeTime, Spinner} from '@primer/react'
import {useCallback, useMemo, useRef, useState} from 'react'

import {useDeleteWorkbenchMutation} from '../hooks/use-delete-workbench-mutation'
import {useFavoriteWorkbenchMutation} from '../hooks/use-favorite-workbench-mutation'
import {useSparkUrls} from '../hooks/use-spark-urls'
import {DeleteSparkDialog} from './DeleteSparkDialog'
import styles from './SparksList.module.css'

type FavoriteWorkbenchFn = ReturnType<typeof useFavoriteWorkbenchMutation>['favoriteWorkbench']
type ShowUrlFn = ReturnType<typeof useSparkUrls>['showUrl']

interface SparksListProps {
  items: Workbench[] | undefined
  sparkEnabled: boolean
}

export const SparksList: React.FC<SparksListProps> = ({items, sparkEnabled}) => {
  const [openDeleteDialogItem, setOpenDeleteDialogItem] = useState<Workbench | null>(null)
  const dialogReturnFocusRef = useRef<HTMLButtonElement | null>(null)

  const {width} = useViewport()
  const {showUrl} = useSparkUrls()

  const [, , , entitlementsQuotaReadOnly] = useGlobalReadOnly()

  const {favoriteWorkbench} = useFavoriteWorkbenchMutation()
  const {deleteWorkbench} = useDeleteWorkbenchMutation()

  useLayoutEffect(() => {
    if (openDeleteDialogItem) return

    const anchorElement = dialogReturnFocusRef.current
    if (!anchorElement) return

    if (anchorElement.isConnected) {
      anchorElement.focus()
    }

    dialogReturnFocusRef.current = null
  }, [openDeleteDialogItem])

  const handleDeleteItem = useCallback(
    (id: string) => {
      deleteWorkbench(id)
      setOpenDeleteDialogItem(null)
    },
    [deleteWorkbench],
  )

  const handleDeleteClick = useCallback((item: Workbench, anchorElement: HTMLButtonElement | null) => {
    setOpenDeleteDialogItem(item)
    dialogReturnFocusRef.current = anchorElement
  }, [])

  const handleDeleteClose = useCallback(() => {
    setOpenDeleteDialogItem(null)
  }, [])

  const loading = items === undefined

  const sortedItems = useMemo(() => {
    return [...(items ?? [])].sort((a, b) => {
      // Handle cases where updatedAt might be undefined
      if (!a.updatedAt) return 1
      if (!b.updatedAt) return -1
      return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
    })
  }, [items])

  return (
    <>
      {loading && (
        <div className={styles.spinner}>
          <Spinner size="small" srText="Loading" />
        </div>
      )}
      {!loading && sortedItems.length === 0 && <span className={styles.blankslate}>Nothing to see here… yet.</span>}
      {!loading && sortedItems.length > 0 && (
        <ListView title="List of sparks" className={styles.sparksList}>
          {sortedItems.map(item => (
            <SparkListItem
              key={item.id}
              item={item}
              sparkEnabled={sparkEnabled}
              entitlementsQuotaReadOnly={entitlementsQuotaReadOnly}
              width={width}
              showUrl={showUrl}
              favoriteWorkbench={favoriteWorkbench}
              onDeleteClick={handleDeleteClick}
            />
          ))}
        </ListView>
      )}
      {openDeleteDialogItem && (
        <DeleteSparkDialog workbench={openDeleteDialogItem} onCancel={handleDeleteClose} onConfirm={handleDeleteItem} />
      )}
    </>
  )
}

type SparkListItemProps = {
  item: Workbench
  sparkEnabled: boolean
  entitlementsQuotaReadOnly: boolean
  width: number | undefined
  showUrl: ShowUrlFn
  favoriteWorkbench: FavoriteWorkbenchFn
  onDeleteClick: (item: Workbench, anchorElement: HTMLButtonElement | null) => void
}

const SparkListItem: React.FC<SparkListItemProps> = ({
  item,
  sparkEnabled,
  entitlementsQuotaReadOnly,
  width,
  showUrl,
  favoriteWorkbench,
  onDeleteClick,
}) => {
  const actionBarAnchorRef = useRef<HTMLElement | null>(null)

  const resolveOverflowToggle = useCallback(() => {
    if (!actionBarAnchorRef.current) return null
    if (actionBarAnchorRef.current instanceof HTMLButtonElement) return actionBarAnchorRef.current
    return actionBarAnchorRef.current.querySelector<HTMLButtonElement>('button[data-test-id="overflow-menu-anchor"]')
  }, [])

  return (
    <ListItem
      title={
        <ListItemTitle
          value={item.name}
          href={sparkEnabled ? showUrl(item.id, item.billableOwner.login, item.runtime.app.friendlyName) : undefined}
        >
          {item.deploy && (
            <Label variant="success" className="ml-2">
              Published
            </Label>
          )}
          {entitlementsQuotaReadOnly && (
            <Label variant="primary" className="ml-2">
              Read-only
            </Label>
          )}
          {!sparkEnabled && (
            <Label variant="attention" className="ml-2">
              Not available
            </Label>
          )}
          {item.runtime.app.isInBetaEnvironment && (
            <Label variant="accent" className="ml-2">
              Beta
            </Label>
          )}
        </ListItemTitle>
      }
      metadataContainerClassName={styles.ListItemMetadataContainer}
      metadata={
        width !== undefined &&
        width >= 768 && (
          <ListItemMetadata>
            {item.favorite ? (
              <IconButton
                variant="invisible"
                icon={StarFillIcon}
                title={`Unfavorite ${item.name}`}
                aria-label="Unfavorite this spark"
                className={styles.starfillIcon}
                onClick={() => favoriteWorkbench({id: item.id, favorite: false})}
              />
            ) : (
              <IconButton
                variant="invisible"
                icon={StarIcon}
                title={`Unfavorite ${item.name}`}
                aria-label="Favorite this spark"
                onClick={() => favoriteWorkbench({id: item.id, favorite: true})}
              />
            )}
          </ListItemMetadata>
        )
      }
      secondaryActions={
        <ListItemActionBar
          label="Options"
          anchorRef={actionBarAnchorRef}
          staticMenuActions={[
            {
              key: 'favorite-spark',
              render: () => {
                if (width && width < 768) {
                  if (item.favorite) {
                    return (
                      <ActionList.Item onSelect={() => favoriteWorkbench({id: item.id, favorite: false})}>
                        <ActionList.LeadingVisual>
                          <StarFillIcon />
                        </ActionList.LeadingVisual>
                        Unfavorite
                      </ActionList.Item>
                    )
                  } else {
                    return (
                      <ActionList.Item onSelect={() => favoriteWorkbench({id: item.id, favorite: true})}>
                        <ActionList.LeadingVisual>
                          <StarIcon />
                        </ActionList.LeadingVisual>
                        Favorite
                      </ActionList.Item>
                    )
                  }
                }
              },
            },
            {
              key: 'live-deployment-url',
              render: () => {
                if (item.deploy) {
                  return (
                    <ActionList.LinkItem
                      href={workbenchDeployUrl({
                        friendlyName: item.runtime.app.friendlyName,
                        deployLogin: item.deploy.deployLogin,
                        domainBase: item.deploy.domainBase,
                      })}
                    >
                      <ActionList.LeadingVisual>
                        <LinkExternalIcon />
                      </ActionList.LeadingVisual>
                      Visit spark
                    </ActionList.LinkItem>
                  )
                }
              },
            },
            {
              key: 'view-repository',
              render: () => {
                if (item.repositoryUrl) {
                  return (
                    <ActionList.LinkItem href={item.repositoryUrl}>
                      <ActionList.LeadingVisual>
                        <RepoIcon />
                      </ActionList.LeadingVisual>
                      View repository
                    </ActionList.LinkItem>
                  )
                }
              },
            },
            {
              key: 'divider',
              render: () => <ActionList.Divider />,
            },
            {
              key: 'delete-spark',
              render: () => (
                <ActionList.Item variant="danger" onSelect={() => onDeleteClick(item, resolveOverflowToggle())}>
                  <ActionList.LeadingVisual>
                    <TrashIcon />
                  </ActionList.LeadingVisual>
                  Delete
                </ActionList.Item>
              ),
            },
          ]}
        />
      }
    >
      <ListItemLeadingContent>
        <ListItemLeadingVisual description="Sparkle icon" icon={SparkleFillIcon} className="fgColor-muted" />
      </ListItemLeadingContent>
      <ListItemMainContent>
        <ListItemDescription>
          <ErrorBoundary fallback={null}>
            {item.updatedAt && (
              <>
                Last updated <RelativeTime date={new Date(item.updatedAt)} />
              </>
            )}
          </ErrorBoundary>
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}

try{ SparksList.displayName ||= 'SparksList' } catch {}
try{ SparkListItem.displayName ||= 'SparkListItem' } catch {}