// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {MediaContentItem} from '@github-ui/copilot-chat/utils/copilot-chat-types'

import type {WorkspaceEditorRoutePayload} from '../utilities/workspace-editor-types'
import type {DeploymentVisibilitySetting} from './deployment-types'
import type {FileDescription} from './spark-history-types'

export interface WorkbenchRoutePayload extends WorkspaceEditorRoutePayload {
  friendlyName?: string
  login?: string
  workbench: Workbench
  deploy?: Deploy
  acaJwtInfo?: ACAJwtInfo
  previewDeploy?: Deploy
  repositoryChannel?: string
  userAnalyticsTrackingId: string
  organizations?: UserOrganization[]
  createRepoOwner?: string
  canDeployToAllGithub?: boolean
}

export interface Runtime {
  app: RuntimeApp
  owner: RuntimeOwner
}

export interface RuntimeApp {
  permanentName: string
  readOnlyKv: boolean
  deploymentVisibility: {
    setting: DeploymentVisibilitySetting
    organizationId: number | null
  }
  friendlyName: string
  isInBetaEnvironment: boolean
}

export interface RuntimeOwner {
  permanentName: string
  deployLogin: string
  deploymentDomainBase: string
}

export interface Deploy {
  createdAt: string
  deployLogin: string
  displayName: string
  domainBase: string
  revision?: string
}

export interface ACAJwtInfo {
  appName: string
  payload: string
  proxyPayload: string
  userLogin: string
}

export interface UserOrganization {
  id: number
  login: string
  name: string
  primaryAvatarUrl: string
}

export interface Iteration {
  iteration_type: 'ai' | 'user' | 'from_repository'
  prompt?: string
  sha?: string
  files: Record<string, FileDescription>
  id?: number
  parentId?: number | null
  parentSha?: string | null
  suggestions?: string[]
  error?: {message: string}
  branchName?: string
  intentSummary?: string
  completionSummary?: string[]
}

// Data used for keeping track of current iteration info we need,
// particularly for telemetry between start/completed...
export interface IterationTracking {
  iterationStartTime: number | null
  iterationStep: string
  iterationMethod: string
  iterationUuid: string
}

// This is the structure of data returned from the ruby controller.
// It's passed in the route payload, but also by some direct API calls.
export interface Workbench {
  id: string
  name: string
  previousRefinements: Iteration[] // User entered refinement prompts & previously selected suggestions
  title: string // Model generated title
  description: string // Model generated description
  shouldGenerateInitialPrompt: boolean
  updatedAt: string
  createdAt: string
  currentRefinementId?: number | null
  repositoryUrl?: string
  billableOwner: {
    id: number
    login: string
    type: 'User' | 'Organization'
  }
  deploy?: Deploy
  cloudspace_id: string
  runtime: Runtime

  // Sometimes exists. Added by workbench_controller#index only
  favorite?: boolean
  cloudspace_active?: boolean
  cloudspace_name?: string
  cloudspace_guid?: string
  cloudspace_last_used_at?: string
}

export type WorkbenchMediaContentItem = Omit<MediaContentItem, 'mediaType'> & {media_type: string}

export const Panel = {
  THEME: 'theme',
  AI: 'ai',
  ASSETS: 'assets',
  DATA: 'data',
  ITERATE: 'iterate',
} as const
export type Panel = (typeof Panel)[keyof typeof Panel]

export const Region = {
  ...Panel,
  HISTORY: 'history', // removed?
  EDITOR: 'editor',
  PREVIEW: 'preview',
  TARGETED_EDITS: 'targetedEdits',
  DEPLOY_BUTTON: 'deployButton',
  SETTINGS: 'settings',
} as const
export type Region = (typeof Region)[keyof typeof Region]

export type SparkAgentModel = 'claude-3.7-sonnet' | 'claude-sonnet-4' | 'claude-sonnet-4.5'

export type WorkingMode = 'code' | 'split' | 'preview'

export type IterationMetadata = {
  prompt: string
  suggestions: string[]
  iteration_type: 'ai' | 'user' | 'from_repository'
  message: string
  parentSha: string | null
  files: {
    [key: string]: {
      editType: 'create' | 'update' | 'delete' | 'rename'
      fileName: string
    }
  }
  branchName: string
  sha: string
}
