import {usePreviousValue} from '@github-ui/use-previous-value'
import {createContext, type PropsWithChildren, useContext, useEffect, useMemo, useState} from 'react'

import {uuid} from '../utilities/uuid'

/**
 * Page visibility state.
 */
interface IPageVisibilityState {
  /**
   * State of the page.
   */
  state: 'visible' | 'hidden'

  /**
   * Unique identifier for the current visibility state.
   */
  sessionId: string

  /**
   * Timestamp when the visibility state changed to
   * the current one.
   */
  stateChangeTimestamp: number

  /**
   * Duration of previous visibility state in milliseconds.
   */
  previousStateDurationMs: number
}

/**
 * Helper to get a new visibility state attributes.
 */
function getNewState(): Pick<IPageVisibilityState, 'state' | 'stateChangeTimestamp' | 'sessionId'> {
  const state = !document.hidden ? 'visible' : 'hidden'

  return {
    state,
    stateChangeTimestamp: performance.now(),
    sessionId: uuid(),
  }
}

/**
 * Current page visibility state of the app.
 */
export const PAGE_VISIBILITY_STATE: IPageVisibilityState = Object.freeze({
  ...getNewState(),
  previousStateDurationMs: 0,
})

/**
 * Page visibility context.
 */
const PageVisibilityContext = createContext(PAGE_VISIBILITY_STATE)

/**
 * Provides page visibility context.
 */
export function PageVisibilityProvider(props: PropsWithChildren<{}>) {
  const [currentState, setState] = useState<Omit<IPageVisibilityState, 'previousStateDurationMs'>>(() => {
    return PAGE_VISIBILITY_STATE
  })
  const previousState = usePreviousValue(currentState)

  // subscribe to browser page visibility changes
  useEffect(() => {
    const handleVisibilityChange = () => {
      setState(getNewState())
    }

    document.addEventListener('visibilitychange', handleVisibilityChange)
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange)
    }
  }, [])

  const previousStateChangeTimestamp = previousState?.stateChangeTimestamp ?? currentState.stateChangeTimestamp

  // enhance current information with the duration time of the previous state
  const value: IPageVisibilityState = useMemo(() => {
    return {
      sessionId: currentState.sessionId,
      state: currentState.state,
      stateChangeTimestamp: currentState.stateChangeTimestamp,
      previousStateDurationMs: currentState.stateChangeTimestamp - previousStateChangeTimestamp,
    }
  }, [currentState.sessionId, currentState.stateChangeTimestamp, currentState.state, previousStateChangeTimestamp])

  return <PageVisibilityContext.Provider value={value} {...props} />
}

/**
 * Use information about web page visibility.
 */
export function usePageVisibility(): IPageVisibilityState {
  return useContext(PageVisibilityContext)
}

try{ PAGE_VISIBILITY_STATE.displayName ||= 'PAGE_VISIBILITY_STATE' } catch {}
try{ PageVisibilityContext.displayName ||= 'PageVisibilityContext' } catch {}
try{ PageVisibilityProvider.displayName ||= 'PageVisibilityProvider' } catch {}