import {ScopedCommands} from '@github-ui/ui-commands'
import {PaperAirplaneIcon} from '@primer/octicons-react'
import {TextInput} from '@primer/react'
import {type FormEvent, useEffect, useState} from 'react'

import {useTargetedEditsContext} from '../contexts/TargetedEditsContext'
import type {ElementPayload} from '../targeted-edits/types'
import {SPARK_LIVE_PREVIEW_IFRAME_ID, SPARK_PREVIEW_CONTAINER_ID} from './PreviewArea/Constants'
import styles from './TargetedEditsInput.module.css'

interface TargetedEditsInputProps {
  element: ElementPayload
  onSubmit: (prompt: string, location: NonNullable<ElementPayload['location']>) => void
}

export const TARGETED_EDITS_INPUT_ID = 'targeted-edits-input'

export function TargetedEditsInput({element, onSubmit}: TargetedEditsInputProps) {
  const {inputRef, lastFocusedButtonLoc, themePanelRef} = useTargetedEditsContext()

  const [previewAreaBounds, setPreviewAreaBounds] = useState<{
    top: number
    left: number
    width: number
    height: number
  }>({
    top: 0,
    left: 0,
    width: 0,
    height: 0,
  })

  const [prompt, setPrompt] = useState<string>('')

  useEffect(() => {
    const sparkPreviewContainer = document.getElementById(SPARK_PREVIEW_CONTAINER_ID)! as HTMLDivElement
    const updatePosition = () => {
      const {top, left, width, height} = sparkPreviewContainer.getBoundingClientRect()
      setPreviewAreaBounds({top, left, width, height})
    }

    updatePosition()

    const resizeObserver = new ResizeObserver(() => {
      updatePosition()
    })
    resizeObserver.observe(sparkPreviewContainer)

    return () => {
      resizeObserver.unobserve(sparkPreviewContainer)
      resizeObserver.disconnect()
    }
  }, [])

  const {position} = element

  const handleSubmit = async (e?: FormEvent) => {
    e?.preventDefault()

    if (prompt.trim().length === 0) return

    const location = element.location ?? element.component.location!

    onSubmit(prompt, location)
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // Escape = cancel and restore focus to overlay button
    // Shift+Enter = cycle to theme panel (next in cycle: element → input → theme panel → element)

    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Need direct keydown handler to communicate with iframe
    if (e.key === 'Escape') {
      e.preventDefault()

      // Tell iframe to restore focus to the overlay button
      const iframe = document.getElementById(SPARK_LIVE_PREVIEW_IFRAME_ID) as HTMLIFrameElement
      if (iframe && iframe.contentWindow) {
        let targetOrigin = '*'
        if (iframe.src) {
          try {
            const url = new URL(iframe.src, window.location.origin)
            targetOrigin = url.origin
          } catch {
            targetOrigin = '*'
          }
        }
        iframe.contentWindow.postMessage(
          {
            type: 'spark:designer:bridge:restore-focus',
            buttonDataLoc: lastFocusedButtonLoc.current,
          },
          targetOrigin,
        )
      }
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Need direct keydown handler for cycle navigation
    } else if (e.key === 'Enter' && e.shiftKey) {
      e.preventDefault()

      // Cycle to theme panel (next step in cycle)
      if (themePanelRef.current) {
        const focusableElement = themePanelRef.current.querySelector<HTMLElement>(
          'button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
        )
        if (focusableElement) {
          focusableElement.focus()
        }
      }
    }
  }

  return (
    <div
      id={TARGETED_EDITS_INPUT_ID}
      className={styles.container}
      style={{
        position: 'fixed',
        zIndex: 10,
        top: previewAreaBounds.top + position.top + position.height + 8,
        left: previewAreaBounds.left + position.left + position.width / 2,
        transform: 'translateX(-50%)', // This centers the element horizontally
      }}
    >
      <ScopedCommands commands={{'github:submit-form': () => handleSubmit()}}>
        <form className={styles.form} onSubmit={handleSubmit}>
          <TextInput
            ref={inputRef}
            block
            trailingAction={<TextInput.Action type="submit" icon={PaperAirplaneIcon} aria-label="Send now" />}
            placeholder="Make a quick change here..."
            value={prompt}
            onChange={e => setPrompt(e.target.value)}
            onKeyDown={handleKeyDown}
          />
        </form>
      </ScopedCommands>
    </div>
  )
}

try{ TargetedEditsInput.displayName ||= 'TargetedEditsInput' } catch {}