/**
 * Asset management utilities for workbench
 * Provides a unified interface for handling assets (images, videos, audio, documents)
 * in both legacy and new asset systems
 */

export type AssetCategory = 'image' | 'audio' | 'video' | 'document'

export interface Asset {
  name: string // filename extracted from path
  path: string // full path including filename
  size: number // file size in bytes
  sizePretty: string // human-readable file size
  category: AssetCategory // determined from file extension
  content?: string // lazy-loaded content URL
}

/**
 * File type configuration for supported assets
 */
interface FileTypeConfig {
  extensions: string[]
  category: AssetCategory
  mimeTypes: string[]
}

// Configuration for supported file types
const FILE_TYPE_CONFIG: FileTypeConfig[] = [
  {
    extensions: ['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp'],
    category: 'image',
    mimeTypes: ['image/png', 'image/jpeg', 'image/gif', 'image/svg+xml', 'image/webp'],
  },
  {
    extensions: ['pdf'],
    category: 'document',
    mimeTypes: ['application/pdf'],
  },
  {
    extensions: ['mp3', 'ogg'],
    category: 'audio',
    mimeTypes: ['audio/mpeg', 'audio/ogg'],
  },
  {
    extensions: ['mp4', 'webm'],
    category: 'video',
    mimeTypes: ['video/mp4', 'video/webm'],
  },
]

const ASSETS_BASE_PATH = 'src/assets/'

/**
 * Utility functions for file type detection
 */
function getAllExtensions(includeMedia: boolean): string[] {
  const configs = includeMedia ? FILE_TYPE_CONFIG : FILE_TYPE_CONFIG.filter(config => config.category === 'image')
  return configs.flatMap(config => config.extensions)
}

function getFileTypeConfig(extension: string, includeMedia: boolean): FileTypeConfig | undefined {
  const configs = includeMedia ? FILE_TYPE_CONFIG : FILE_TYPE_CONFIG.filter(config => config.category === 'image')
  return configs.find(config => config.extensions.includes(extension.toLowerCase()))
}

/**
 * Convert relative asset path to URL path for API calls
 */
function getAssetApiPath(assetPath: string): string {
  return assetPath.includes(ASSETS_BASE_PATH)
    ? assetPath.substring(assetPath.indexOf(ASSETS_BASE_PATH) + ASSETS_BASE_PATH.length)
    : assetPath
}

/**
 * Public API Functions
 */
/**
 * Get asset category from filename
 */
export function getAssetCategory(filename: string): AssetCategory {
  const extension = filename.split('.').pop()?.toLowerCase() || ''
  const config = getFileTypeConfig(extension, true)
  return config?.category || 'document'
}

/**
 * Get asset directory for file organization
 */
export function getAssetDirectory(filename: string): string {
  const category = getAssetCategory(filename)
  switch (category) {
    case 'image':
      return 'images'
    case 'video':
      return 'video'
    case 'audio':
      return 'audio'
    case 'document':
    default:
      return 'documents'
  }
}

/**
 * Get supported file extensions for file input
 */
export function getSupportedAssetExtensions(includeMedia: boolean): string[] {
  return getAllExtensions(includeMedia).map(ext => `.${ext}`)
}

/**
 * Convert file size to human-readable string
 */
export function getReadableFileSize(bytes: number): string {
  if (bytes === 0) return '0 bytes'

  const units = ['bytes', 'KB', 'MB', 'GB']
  let size = bytes
  let unitIndex = 0

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024
    unitIndex++
  }

  const formatted = unitIndex === 0 ? size.toString() : size.toFixed(unitIndex === 1 ? 0 : 1)
  return `${formatted} ${units[unitIndex]}`
}

/**
 * Get formatted asset information string for display
 */
export function getAssetInfo(asset: Asset): string {
  return `${asset.category} · ${asset.sizePretty}`
}

/**
 * Check if a file path is an asset file that should be handled specially
 */
export function isAssetFile(filePath: string): boolean {
  const extension = filePath.split('.').pop()?.toLowerCase() || ''
  return FILE_TYPE_CONFIG.some(config => config.extensions.includes(extension))
}

/**
 * Validate files for upload and return valid and invalid file lists
 */
export function validateFilesForUpload(
  files: File[],
  maxFileSize: number,
): {validFiles: File[]; invalidFiles: string[]} {
  const validFiles: File[] = []
  const invalidFiles: string[] = []

  for (const file of files) {
    if (file.size > maxFileSize) {
      invalidFiles.push(`${file.name} (${getReadableFileSize(file.size)})`)
    } else {
      validFiles.push(file)
    }
  }

  return {validFiles, invalidFiles}
}

/**
 * Backend API Communication
 */

// Interface for backend asset responses
interface BackendAssetResponse {
  path: string
  size: number
  createdAt: string
  modifiedAt: string
}

/**
 * Sanitize filename using the same logic as backend
 */
function sanitizeFilename(filename: string): string {
  return filename
    .replace(/[/\\:*?"<>|]/g, '_')
    .replace(/\.\./g, '_')
    .replace(/\s+/g, '_') // Replace spaces with underscores
    .trim()
    .substring(0, 255) // Limit filename length for file system compatibility
}

/**
 * Upload an asset file to the agent server
 */
export async function uploadAssetToAgent(
  file: File,
  filename: string,
  fetchFromCodespaceApi: (url: string, options?: RequestInit) => Promise<Response>,
): Promise<void> {
  // Sanitize filename before encoding to match backend processing
  const sanitizedFilename = sanitizeFilename(filename)

  const response = await fetchFromCodespaceApi('/asset/upload', {
    method: 'POST',
    headers: {
      'x-filename': sanitizedFilename,
    },
    body: file,
  })

  if (!response.ok) {
    let errorData
    try {
      errorData = await response.json()
    } catch {
      throw new Error(`Upload failed with status ${response.status}`)
    }

    // Create detailed error object with parsed API response
    const error = new Error(errorData.message || `Upload failed with status ${response.status}`) as Error & {
      code?: string
      data?: {
        fileSize?: number
        fileLimit?: number
        totalLimit?: number
        totalCurrent?: number
      }
    }

    if (errorData.code) {
      error.code = errorData.code
    }

    if (errorData.data) {
      error.data = errorData.data
    }

    throw error
  }
}

/**
 * Get list of uploaded assets from agent server
 */
export async function getAssetsList(
  fetchFromCodespaceApi: (url: string, options?: RequestInit) => Promise<Response>,
): Promise<Asset[]> {
  try {
    const response = await fetchFromCodespaceApi('/asset/list', {
      method: 'GET',
    })

    if (!response.ok) {
      return []
    }

    const result = await response.json()
    const backendAssets: BackendAssetResponse[] = result.data?.assets || []

    return backendAssets.map(backendAsset => {
      const name = backendAsset.path.split('/').pop() || 'unknown'
      return {
        path: backendAsset.path,
        name,
        size: backendAsset.size,
        sizePretty: getReadableFileSize(backendAsset.size),
        category: getAssetCategory(name),
      }
    })
  } catch {
    return []
  }
}

/**
 * Download an asset file from agent server as a blob
 */
export async function downloadAssetFromAgent(
  assetPath: string,
  fetchFromCodespaceApi: (url: string, options?: RequestInit) => Promise<Response>,
): Promise<Blob | null> {
  try {
    const relativePath = getAssetApiPath(assetPath)
    const response = await fetchFromCodespaceApi(`/asset/stream/${relativePath}`, {
      method: 'GET',
    })

    return response.ok ? await response.blob() : null
  } catch {
    return null
  }
}

/**
 * Delete an asset from the agent server
 */
export async function deleteAssetFromAgent(
  assetPath: string,
  fetchFromCodespaceApi: (url: string, options?: RequestInit) => Promise<Response>,
): Promise<void> {
  const relativePath = getAssetApiPath(assetPath)
  const response = await fetchFromCodespaceApi(`/asset/${relativePath}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.message || `Delete failed with status ${response.status}`)
  }
}

/**
 * Create content URL from blob, using blob URLs for audio/video/PDF and data URLs for images
 */
export async function createAssetContentUrl(
  blob: Blob,
  filename: string,
  includeMedia: boolean,
  blobUrlsSet: Set<string>,
): Promise<string> {
  const extension = filename.split('.').pop()?.toLowerCase() || ''
  const config = getFileTypeConfig(extension, includeMedia)

  if (config?.category === 'audio' || config?.category === 'video' || config?.category === 'document') {
    // Create blob URL for audio/video/document files for better performance and PDF embedding support
    const blobUrl = URL.createObjectURL(blob)
    blobUrlsSet.add(blobUrl)
    return blobUrl
  } else {
    // Convert blob to base64 data URL for images only
    return new Promise<string>((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => resolve(reader.result as string)
      reader.onerror = reject
      reader.readAsDataURL(blob)
    })
  }
}

/**
 * Download an asset to the user's computer
 */
export function downloadAssetToComputer(asset: Asset): void {
  if (!asset.content) return

  try {
    let downloadUrl: string
    let needsCleanup = false

    if (asset.content.startsWith('blob:')) {
      downloadUrl = asset.content
    } else {
      // Convert data URL to blob for download
      const contentParts = asset.content.split(',')
      if (contentParts.length < 2 || !contentParts[1]) return

      const byteCharacters = atob(contentParts[1])
      const byteNumbers = new Array(byteCharacters.length)
      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i)
      }
      const byteArray = new Uint8Array(byteNumbers)
      const blob = new Blob([byteArray])
      downloadUrl = URL.createObjectURL(blob)
      needsCleanup = true
    }

    const link = document.createElement('a')
    link.href = downloadUrl
    link.download = asset.name
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)

    if (needsCleanup) {
      URL.revokeObjectURL(downloadUrl)
    }
  } catch {
    // Silent fail for download errors
  }
}

/**
 * Cleanup utilities
 */

/**
 * Clean up blob URL for an asset
 */
export function cleanupAssetBlobUrl(asset: Asset, blobUrlsSet: Set<string>): void {
  if (asset.content && asset.content.startsWith('blob:')) {
    URL.revokeObjectURL(asset.content)
    blobUrlsSet.delete(asset.content)
  }
}

/**
 * Clean up blob URLs to prevent memory leaks
 */
export function cleanupBlobUrl(urls: string | string[]): void {
  const urlsToCleanup = Array.isArray(urls) ? urls : [urls]

  for (const url of urlsToCleanup) {
    if (url && url.startsWith('blob:')) {
      URL.revokeObjectURL(url)
    }
  }
}

/**
 * Normalize asset path to start with src/assets/
 */
function normalizeAssetPath(path: string): string {
  // If path already starts with src/assets/, return as-is
  if (path.startsWith('src/assets/')) {
    return path
  }

  // If path contains src/assets/ anywhere, extract everything from src onwards
  const srcAssetsIndex = path.indexOf('src/assets/')
  if (srcAssetsIndex !== -1) {
    return path.substring(srcAssetsIndex)
  }

  // Otherwise, return the original path unchanged
  return path
}

/**
 * File Management and Comparison
 */
export function shouldRefreshAssets(fileList: Array<{path: string}>, currentAssets: Asset[]): boolean {
  // Extract and normalize asset paths from the file list (files in assets directory)
  const assetPaths = fileList
    .filter(entry => entry.path.includes('/assets/'))
    .map(entry => normalizeAssetPath(entry.path))
    .sort()

  // Get and normalize current asset paths for comparison
  const currentAssetPaths = currentAssets.map(asset => normalizeAssetPath(asset.path)).sort()

  // Check if the asset paths have changed
  const lengthsDiffer = currentAssetPaths.length !== assetPaths.length
  const pathsDiffer = currentAssetPaths.some((path, index) => path !== assetPaths[index])
  const shouldRefresh = lengthsDiffer || pathsDiffer

  return shouldRefresh
}
