import {announce as announceToScreenReader} from '@github-ui/aria-live'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {
  ArrowUpRightIcon,
  DotFillIcon,
  EyeIcon,
  IdBadgeIcon,
  LockIcon,
  OrganizationIcon,
  PencilIcon,
  RocketIcon,
  SyncIcon,
  TriangleDownIcon,
} from '@primer/octicons-react'
import {ActionList, ActionMenu, AnchoredOverlay, Button, FormControl, Spinner, TextInput} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useCallback, useEffect, useId, useRef, useState} from 'react'

import {usePublishingContext} from '../../contexts/PublishingContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import type {DeploymentVisibilitySetting} from '../../types/deployment-types'
import type {UserOrganization, WorkbenchRoutePayload} from '../../types/workbench-types'
import styles from './PublishDropdown.module.css'
import {PublishOrgSelector} from './PublishOrgSelector'

const DeploymentVisibilityOptions: Record<
  DeploymentVisibilitySetting,
  {title: string; description: string; icon: React.ReactElement}
> = {
  only_owner: {
    title: 'Only you',
    description: 'Private no matter what',
    icon: <LockIcon />,
  },
  selected_orgs: {
    title: 'Organization',
    description: 'All members of a selected organization',
    icon: <OrganizationIcon />,
  },
  github: {
    title: 'All GitHub users',
    description:
      'Anyone with the link can see content and data contained in this spark. Be careful with sensitive information.',
    icon: <IdBadgeIcon />,
  },
}

type DataAccessSetting = 'read_only' | 'write_access'

const DataAccessOptions: Record<DataAccessSetting, {title: string; description: string; icon: React.ReactElement}> = {
  read_only: {
    title: 'Read-Only',
    description: 'Only you can edit data, other users will have view-only access',
    icon: <EyeIcon />,
  },
  write_access: {
    title: 'Write Access',
    description: 'Users can view and modify content',
    icon: <PencilIcon />,
  },
}

const getPublishingText = (publishingStatus: string) => {
  switch (publishingStatus) {
    case 'publishingFirstTime':
    case 'republishing':
      return 'Publishing'
    case 'publishedFirstTime':
    case 'published':
    case 'republishFailed':
      return 'Published'
    case 'unpublished':
    default:
      return 'Publish'
  }
}

const getButtonIcon = (publishingStatus: string) => {
  switch (publishingStatus) {
    case 'publishingFirstTime':
      return <Spinner size="small" />
    case 'publishedFirstTime':
    case 'published':
    case 'republishing':
    case 'republishFailed':
      return (
        <span className={styles.dotContainer}>
          <DotFillIcon size="small" className="fgColor-success" />
          <span className={styles.pulsingDot} />
        </span>
      )
    case 'unpublished':
    default:
      return null
  }
}

interface PublishDropdownProps {
  className?: string
  variant?: 'menu' | 'button'
  hidden?: boolean
}

export const PublishDropdown = ({className, variant = 'button', hidden}: PublishDropdownProps) => {
  const workbench = useWorkbenchContext()
  const visibilityControlId = useId()
  const visibilityLabelId = useId()
  const visibilityValueId = useId()
  const visibilityDescriptionId = useId()
  const dataAccessControlId = useId()
  const dataAccessLabelId = useId()
  const dataAccessValueId = useId()

  // extract the orgs. the weird null-coalescing is to fight storybook test failures
  // due to the router payload not being available. don't have the energy to work around it.
  const {organizations, canDeployToAllGithub = true} = useRoutePayload<WorkbenchRoutePayload>() ?? {}

  const showDataAccess = isFeatureEnabled('spark_show_data_access_on_publish')

  const [menuOpen, setMenuOpen] = useState(false)
  const [updateState, setUpdateState] = useState<'updating' | 'updated' | 'error' | null>(null)
  const [dataAccessUpdateState, setDataAccessUpdateState] = useState<'updating' | 'updated' | 'error' | null>(null)

  const {
    publishingStatus,
    publishedUrl,
    startDeploymentPipeline,
    canCurrentlyPublish,
    isPublishUpToDate,
    visibility: contextVisibility,
    visibilityOrganizationId,
    updateVisibility,
    updateDataAccess,
    readOnlyKv,
    cancelPublishing,
  } = usePublishingContext()

  // Local state for visibility
  const [localVisibility, setLocalVisibility] = useState<DeploymentVisibilitySetting>(contextVisibility)

  const dataAccess: DataAccessSetting = readOnlyKv ? 'read_only' : 'write_access'

  // Find the default selected organization based on visibilityOrganizationId
  const defaultSelectedOrganization = visibilityOrganizationId
    ? organizations?.find(org => org.id === visibilityOrganizationId)
    : undefined

  const [selectedOrganization, setSelectedOrganization] = useState<UserOrganization | undefined>(
    defaultSelectedOrganization,
  )

  // Sync local state with context when context changes
  useEffect(() => {
    // If user is not allowed to deploy to all GitHub users and currently has github visibility,
    // automatically change to only_owner for safety
    if (!canDeployToAllGithub && contextVisibility === 'github') {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLocalVisibility('only_owner')
      // Also update the backend to reflect this change
      updateVisibility({
        setting: 'only_owner',
        organizationId: null,
      })
    } else {
      setLocalVisibility(contextVisibility)
    }

    // Also update the selected organization when the context organization ID changes
    const newSelectedOrg = visibilityOrganizationId
      ? organizations?.find(org => org.id === visibilityOrganizationId)
      : undefined
    setSelectedOrganization(newSelectedOrg)
  }, [contextVisibility, visibilityOrganizationId, organizations, canDeployToAllGithub, updateVisibility])

  const handleVisibilityChange = useCallback(
    async (newVisibilitySetting: DeploymentVisibilitySetting) => {
      // Update local state immediately for responsive UI
      setLocalVisibility(newVisibilitySetting)

      // Reset selected organization when changing visibility
      if (newVisibilitySetting !== 'selected_orgs') {
        setSelectedOrganization(undefined)
      }

      if (newVisibilitySetting === 'selected_orgs') {
        // For selected_orgs, don't call the API yet - wait for organization selection
        return
      } else {
        // For other visibility types, call the API immediately
        setUpdateState('updating')
        const succeeded = await updateVisibility({
          setting: newVisibilitySetting,
          organizationId: null,
        })
        setUpdateState(succeeded ? 'updated' : 'error')
        setTimeout(() => {
          setUpdateState(null)
        }, 2000)
      }
    },
    [updateVisibility],
  )

  const handleOrgSelectionComplete = useCallback(
    async (orgName: string) => {
      if (localVisibility === 'selected_orgs') {
        // Find the organization ID from the organizations data
        const org = organizations?.find(o => o.login === orgName)
        if (org) {
          setUpdateState('updating')
          const succeeded = await updateVisibility({
            setting: 'selected_orgs',
            organizationId: org.id,
          })
          setUpdateState(succeeded ? 'updated' : 'error')
          setTimeout(() => {
            setUpdateState(null)
          }, 2000)
        }
      }
    },
    [updateVisibility, localVisibility, organizations],
  )

  const handleDataAccessChange = useCallback(
    async (newDataAccess: DataAccessSetting) => {
      const isReadonly = newDataAccess === 'read_only'
      setDataAccessUpdateState('updating')
      const succeeded = await updateDataAccess(isReadonly)
      setDataAccessUpdateState(succeeded ? 'updated' : 'error')
      setTimeout(() => {
        setDataAccessUpdateState(null)
      }, 2000)
    },
    [updateDataAccess],
  )

  // The following code was added in story https://github.com/github/spark/issues/1200
  // Specifically the line: "Can't dismiss the ... menu in the toolbar by clicking in the iFrame unless I specifically click the icon button again"
  // Code is from PR https://github.com/github/github/pull/385456
  // But this leads to really bad behavior in dev, where the iframe gaining any type of focus
  // will close the dialog. It's impossible to use the dialog in dev.
  // useSparkIframeFocus(() => {
  //   if (menuOpen) {
  //     setMenuOpen(false)
  //   }
  // })

  const hasError = publishingStatus === 'republishFailed'
  const canRepublish = !isPublishUpToDate && canCurrentlyPublish
  const statusIndicator = hasError
    ? {variant: 'critical' as const, text: 'Publish failed'}
    : canRepublish
      ? {variant: 'warning' as const, text: 'Unpublished changes'}
      : {variant: 'success' as const, text: 'All changes published'}
  const previousStatusTextRef = useRef(statusIndicator.text)
  const previousStatusVariantRef = useRef(statusIndicator.variant)

  useEffect(() => {
    const isAnnounceableVariant = statusIndicator.variant === 'success' || statusIndicator.variant === 'critical'

    if (menuOpen) {
      previousStatusTextRef.current = statusIndicator.text
      previousStatusVariantRef.current = statusIndicator.variant
      return
    }

    const hasChanged =
      previousStatusTextRef.current !== statusIndicator.text ||
      previousStatusVariantRef.current !== statusIndicator.variant

    if (isAnnounceableVariant && hasChanged) {
      announceToScreenReader(
        statusIndicator.text,
        statusIndicator.variant === 'critical' ? {assertive: true} : undefined,
      )
    }

    previousStatusTextRef.current = statusIndicator.text
    previousStatusVariantRef.current = statusIndicator.variant
  }, [menuOpen, statusIndicator.text, statusIndicator.variant])

  if (variant !== 'menu' && (publishingStatus === 'unpublished' || publishingStatus === 'publishingFirstTime')) {
    return (
      <Button
        className={className}
        variant="primary"
        disabled={!canCurrentlyPublish && publishingStatus === 'unpublished'}
        leadingVisual={getButtonIcon(publishingStatus)}
        onClick={startDeploymentPipeline}
      >
        {getPublishingText(publishingStatus)}
      </Button>
    )
  }

  return (
    <AnchoredOverlay
      open={menuOpen}
      onOpen={() => setMenuOpen(true)}
      onClose={() => setMenuOpen(false)}
      renderAnchor={props => {
        if (variant === 'menu') {
          return (
            <ActionList.Item
              {...props}
              className={className}
              role="menuitem"
              disabled={!canCurrentlyPublish && publishingStatus === 'unpublished'}
              hidden={hidden}
            >
              <ActionList.LeadingVisual>
                {publishingStatus === 'unpublished' ? (
                  <RocketIcon />
                ) : isPublishUpToDate === false ? (
                  <SyncIcon className="fgColor-attention" />
                ) : (
                  getButtonIcon(publishingStatus)
                )}
              </ActionList.LeadingVisual>
              {getPublishingText(publishingStatus)}
            </ActionList.Item>
          )
        }

        return (
          <Button
            {...props}
            className={className}
            variant="default"
            disabled={!canCurrentlyPublish && publishingStatus === 'unpublished'}
            leadingVisual={
              isPublishUpToDate === false ? <SyncIcon className="fgColor-attention" /> : getButtonIcon(publishingStatus)
            }
            hidden={hidden}
            trailingVisual={TriangleDownIcon}
          >
            {isPublishUpToDate ? 'Published' : 'Publish'}
          </Button>
        )
      }}
      width="large"
      preventOverflow={false}
      focusZoneSettings={{disabled: true}}
      overlayProps={{role: 'dialog', 'aria-modal': true, 'aria-label': 'Spark Publish Settings'}}
    >
      <div className={styles.overlayWrapper}>
        <div className={styles.header}>
          <h2 className="f5">{workbench.name}</h2>
          <div role="status" aria-live="polite" aria-atomic="true">
            <InlineMessage size="small" variant={statusIndicator.variant}>
              {statusIndicator.text}
            </InlineMessage>
          </div>
        </div>

        <div className={styles.overlayContent}>
          {publishedUrl && (
            <FormControl>
              <FormControl.Label>Published URL</FormControl.Label>
              <TextInput
                block
                value={publishedUrl}
                readOnly
                onFocus={e => e.target.select()}
                className={styles.publishedUrlContainer}
                trailingAction={<CopyToClipboardButton textToCopy={publishedUrl} />}
              />
            </FormControl>
          )}

          <FormControl>
            <FormControl.Label id={visibilityLabelId} htmlFor={visibilityControlId}>
              Visibility
            </FormControl.Label>
            <div className={styles.visibilityContainer}>
              <ActionMenu>
                <ActionMenu.Button
                  id={visibilityControlId}
                  loading={localVisibility !== 'selected_orgs' && updateState === 'updating'}
                  leadingVisual={DeploymentVisibilityOptions[localVisibility]?.icon}
                  aria-labelledby={`${visibilityLabelId} ${visibilityValueId}`}
                  aria-describedby={visibilityDescriptionId}
                >
                  <span id={visibilityValueId}>{DeploymentVisibilityOptions[localVisibility]?.title}</span>
                </ActionMenu.Button>
                <ActionMenu.Overlay width="medium">
                  <ActionList selectionVariant="single">
                    <ActionList.Item
                      onSelect={() => handleVisibilityChange('only_owner')}
                      selected={localVisibility === 'only_owner'}
                    >
                      <ActionList.LeadingVisual>
                        <LockIcon />
                      </ActionList.LeadingVisual>
                      Only you
                      <ActionList.Description variant="block">Private no matter what</ActionList.Description>
                    </ActionList.Item>
                    <ActionList.Item
                      onSelect={() => handleVisibilityChange('selected_orgs')}
                      selected={localVisibility === 'selected_orgs'}
                      disabled={!organizations || organizations.length === 0}
                    >
                      <ActionList.LeadingVisual>
                        <OrganizationIcon />
                      </ActionList.LeadingVisual>
                      Organization
                      <ActionList.Description variant="block">
                        {!organizations || organizations.length === 0
                          ? 'Join at least one organization to share with its members'
                          : 'All members of a selected organization'}
                      </ActionList.Description>
                    </ActionList.Item>
                    {/* Only show "All GitHub users" option if user is allowed to deploy to all GitHub users */}
                    {canDeployToAllGithub && (
                      <ActionList.Item
                        onSelect={() => handleVisibilityChange('github')}
                        selected={localVisibility === 'github'}
                      >
                        <ActionList.LeadingVisual>
                          <IdBadgeIcon />
                        </ActionList.LeadingVisual>
                        All GitHub users
                        <ActionList.Description variant="block">
                          Anyone with the link who is signed into github.com
                        </ActionList.Description>
                      </ActionList.Item>
                    )}
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
              {localVisibility === 'selected_orgs' && (
                <PublishOrgSelector
                  saving={updateState === 'updating'}
                  selection={selectedOrganization}
                  buttonText={selectedOrganization?.name || 'Select organization'}
                  organizations={organizations ?? []}
                  selectOrg={(selectedOrg: UserOrganization) => {
                    // Find the full organization data from the organizations array
                    const fullOrg = organizations?.find(org => org.name === selectedOrg.name)
                    if (fullOrg) {
                      setSelectedOrganization(fullOrg)
                      handleOrgSelectionComplete(selectedOrg.name)
                    }
                  }}
                  removeOrg={() => setSelectedOrganization(undefined)}
                />
              )}
            </div>
            <FormControl.Caption id={visibilityDescriptionId}>
              {DeploymentVisibilityOptions[localVisibility].description}
            </FormControl.Caption>
          </FormControl>

          {showDataAccess && localVisibility !== 'only_owner' && (
            <FormControl>
              <FormControl.Label id={dataAccessLabelId} htmlFor={dataAccessControlId}>
                Data Access
              </FormControl.Label>
              <ActionMenu>
                <ActionMenu.Button
                  id={dataAccessControlId}
                  loading={dataAccessUpdateState === 'updating'}
                  leadingVisual={DataAccessOptions[dataAccess]?.icon}
                  aria-labelledby={`${dataAccessLabelId} ${dataAccessValueId}`}
                >
                  <span id={dataAccessValueId}>{DataAccessOptions[dataAccess]?.title}</span>
                </ActionMenu.Button>
                <ActionMenu.Overlay width="medium">
                  <ActionList selectionVariant="single">
                    {Object.entries(DataAccessOptions).map(([key, option]) => (
                      <ActionList.Item
                        key={key}
                        onSelect={async () => await handleDataAccessChange(key as DataAccessSetting)}
                        selected={dataAccess === key}
                      >
                        <ActionList.LeadingVisual>{option.icon}</ActionList.LeadingVisual>
                        {option.title}
                        <ActionList.Description variant="block">{option.description}</ActionList.Description>
                      </ActionList.Item>
                    ))}
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
              <FormControl.Caption>{DataAccessOptions[dataAccess].description}</FormControl.Caption>
            </FormControl>
          )}
        </div>

        <div className={styles.overlayFooter}>
          {publishingStatus === 'republishing' ? (
            <Button variant="danger" onClick={cancelPublishing}>
              Cancel
            </Button>
          ) : (
            <Button
              block
              trailingVisual={ArrowUpRightIcon}
              variant="default"
              as="a"
              href={publishedUrl}
              target="_blank"
              inactive={!publishedUrl}
            >
              Visit site
            </Button>
          )}

          <Button
            block
            variant="primary"
            leadingVisual={publishingStatus === 'republishing' ? <Spinner size="small" /> : null}
            onClick={startDeploymentPipeline}
            disabled={canRepublish === false || publishingStatus === 'republishing'}
          >
            {publishingStatus === 'republishing' ? 'Publishing' : 'Publish'}
          </Button>
        </div>
      </div>
    </AnchoredOverlay>
  )
}

try{ PublishDropdown.displayName ||= 'PublishDropdown' } catch {}