import {clsx} from 'clsx'
import {useEffect, useRef, useState} from 'react'

import styles from './StatusPill.module.css'

export type PreviewState = 'loading' | 'ready' | 'error'

interface StatusPillProps {
  state: PreviewState
}

export const StatusPill = ({state}: StatusPillProps) => {
  const [isVisible, setIsVisible] = useState(false)
  const [shouldShow, setShouldShow] = useState(true)
  const hideTimerRef = useRef<NodeJS.Timeout | null>(null)

  useEffect(() => {
    if (state !== 'ready') {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setShouldShow(true)
      // Small delay to allow the entrance animation to play
      const entranceTimer = setTimeout(() => {
        setIsVisible(true)
      }, 50)
      return () => clearTimeout(entranceTimer)
    } else {
      // Show ready state for 2 seconds before hiding
      const timer = setTimeout(() => {
        // Only hide if the state is still 'ready'
        if (state === 'ready') {
          setIsVisible(false)
          // Hide the component after animation completes
          hideTimerRef.current = setTimeout(() => {
            // Double-check the state before hiding completely
            if (state === 'ready') {
              setShouldShow(false)
            }
          }, 300)
        }
      }, 2000)

      return () => {
        clearTimeout(timer)
        if (hideTimerRef.current) {
          clearTimeout(hideTimerRef.current)
        }
      }
    }
  }, [state])

  if (!shouldShow) {
    return null
  }

  const getStatusMessage = () => {
    switch (state) {
      case 'ready':
        return 'Ready'
      case 'error':
        return 'Error'
      default:
        return 'Loading'
    }
  }

  return (
    <div className={clsx(styles.pill, isVisible && styles.visible, styles[state])}>
      <div className={styles.statusDot} />
      <span className={styles.statusMessage}>{getStatusMessage()}</span>
    </div>
  )
}

try{ StatusPill.displayName ||= 'StatusPill' } catch {}