import {SparkleFillIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {memo} from 'react'

import styles from './SparkleSpinner.module.css'

interface SparkleSpinnerProps {
  size?: 'small' | 'medium' | 'large'
  speed?: 'slow' | 'normal'
}

export function UnmemoizedSparkleSpinner(props: SparkleSpinnerProps) {
  const {size = 'medium', speed = 'normal'} = props

  return <SparkleFillIcon aria-hidden="true" className={clsx(styles.sparkleSpinner, styles[size], styles[speed])} />
}

export const SparkleSpinner = memo(UnmemoizedSparkleSpinner)

try{ UnmemoizedSparkleSpinner.displayName ||= 'UnmemoizedSparkleSpinner' } catch {}
try{ SparkleSpinner.displayName ||= 'SparkleSpinner' } catch {}