import {useEffect, useRef, useState} from 'react'

import {SparkleSpinner} from '../../../SparkleSpinner'
import styles from './LoadingMessages.module.css'

function getRandomMessage(messages: string[]): string {
  return messages[Math.floor(Math.random() * messages.length)]!
}

const MESSAGE_DISPLAY_DURATION = 5100

export function LoadingMessages() {
  const [message, setMessage] = useState(() => getRandomMessage(MESSAGES))
  const usedMessagesRef = useRef(new Set<string>())

  // for the fade in/out effect
  const [isVisible, setIsVisible] = useState(true)

  useEffect(() => {
    usedMessagesRef.current.add(message)
  }, [message])

  useEffect(() => {
    let timeoutId: NodeJS.Timeout
    const intervalId = setInterval(() => {
      setIsVisible(false)

      timeoutId = setTimeout(() => {
        const availableMessages = MESSAGES.filter(msg => !usedMessagesRef.current.has(msg))

        if (availableMessages.length === 0) {
          usedMessagesRef.current.clear()
          const newMessage = getRandomMessage(MESSAGES)
          usedMessagesRef.current.add(newMessage)
          setMessage(newMessage)
        } else {
          const newMessage = getRandomMessage(availableMessages)
          usedMessagesRef.current.add(newMessage)
          setMessage(newMessage)
        }

        setIsVisible(true)
      }, 250) // if changing duration, also change in CSS (LoadingMessages.module.css)
    }, MESSAGE_DISPLAY_DURATION)

    return () => {
      clearInterval(intervalId)
      clearTimeout(timeoutId)
    }
  }, [])

  return (
    <div className={styles.container}>
      <SparkleSpinner />
      <div className={styles.loadingDots} style={{opacity: isVisible ? 1 : 0}}>
        {message}
        {['.', '.', '.'].map((dot, index) => (
          // it's fine to use index as key here since the array is static
          // eslint-disable-next-line @eslint-react/no-array-index-key
          <span key={index} className={styles.dot} style={{'--i': index} as React.CSSProperties}>
            {dot}
          </span>
        ))}
      </div>
    </div>
  )
}

