import React, {useCallback, useContext, useRef} from 'react'

import {useTargetedEdits} from '../targeted-edits/use-targeted-edits'

export type TargetedEditsContext = ReturnType<typeof useTargetedEdits>

export const TargetedEditsContext = React.createContext<TargetedEditsContext | undefined>(undefined)

export function TargetedEditsProvider({children}: React.PropsWithChildren) {
  const announcementRef = useRef<HTMLDivElement | null>(null)

  // Function to announce messages to screen readers
  const announce = useCallback((message: string) => {
    if (announcementRef.current) {
      announcementRef.current.textContent = message
    }
  }, [])

  const value = useTargetedEdits(announce)

  return (
    <TargetedEditsContext.Provider value={value}>
      {children}
      {/* Screen reader announcement region for selector mode instructions */}
      <div
        ref={announcementRef}
        role="status"
        aria-live="polite"
        aria-atomic="true"
        style={{
          position: 'absolute',
          left: '-10000px',
          width: '1px',
          height: '1px',
          overflow: 'hidden',
        }}
      />
    </TargetedEditsContext.Provider>
  )
}

export function useTargetedEditsContext() {
  const context = useContext(TargetedEditsContext)
  if (!context) {
    throw new Error('useTargetedEditsContext must be used within a TargetedEditsProvider')
  }
  return context
}

try{ TargetedEditsContext.displayName ||= 'TargetedEditsContext' } catch {}
try{ TargetedEditsProvider.displayName ||= 'TargetedEditsProvider' } catch {}