import styles from './Workbench.module.css'

const appOffsetTop = (rootElement?: HTMLElement | null) => {
  const top = rootElement?.getBoundingClientRect().top ?? 0
  return top > 0 ? top : 0
}

function useAppOffsetTop() {
  const rootRef = useRef<HTMLDivElement | null>(null)
  // eslint-disable-next-line react-hooks/refs
  const [offsetTop, setOffsetTop] = useState(() => appOffsetTop(rootRef?.current))
  const resizeObserver = useCallback(() => {
    setOffsetTop(appOffsetTop(rootRef?.current))
  }, [])

  useResizeObserver(resizeObserver, rootRef)

  return {offsetTop, rootRef}
}

function useHeaderHeight() {
  const headerRef = useRef<HTMLDivElement | null>(null)
  // eslint-disable-next-line react-hooks/refs
  const [headerHeight, setHeaderHeight] = useState(() => headerRef?.current?.clientHeight ?? 0)
  const resizeObserver = useCallback(() => {
    setHeaderHeight(headerRef?.current?.clientHeight ?? 0)
  }, [])

  useResizeObserver(resizeObserver, headerRef)
  return {headerHeight, headerRef}
}

function useHideGlobalNav() {
  const initialHeaderHiddenState = useRef<boolean | null>(null)

  useEffect(() => {
    const headerDiv: HTMLElement | null = document.querySelector('.AppHeader')
    if (!headerDiv) return
    if (initialHeaderHiddenState.current === null) {
      initialHeaderHiddenState.current = headerDiv.hidden
    }
    // Don't do anything if the header is already hidden
    if (headerDiv.hidden) return

    headerDiv.hidden = true

    // On cleanup, restore the header to its original state
    return () => {
      if (headerDiv && initialHeaderHiddenState.current !== null) {
        headerDiv.hidden = initialHeaderHiddenState.current
      }
    }
  }, [])
}

export const WORKBENCH_ROOT_ELEMENT_ID = 'workbench-root'

export function Workbench({Editor}: {Editor: typeof EditorType}) {
  const [selectedPanel, setSelectedPanel] = useState<'iterate' | 'theme' | 'data' | 'ai' | 'assets'>('iterate')
  const receivesNotificationsFromRepository = useFeatureFlag('spark_pull_from_repository')
  const showRepoUrl = useFeatureFlag('copilot_spark_show_repo_url')
  const sendEvent = useAnalytics()
  const isStatusFaviconEnabled = isFeatureEnabled('spark_status_favicon')

  const {
    sidePanelOpen,
    workingMode,
    setWorkingMode,
    createRepositoryModelOpen,
    setCreateRepositoryModelOpen,
    toggleSidePanel,
  } = useWorkbenchUI()
  const {offsetTop, rootRef} = useAppOffsetTop()
  const {headerHeight, headerRef} = useHeaderHeight()
  useHideGlobalNav()

  const {
    copilot: {ssoOrganizations, currentTopic},
    createRepoOwner,
    isNewFilePage,
    repositoryChannel,
  } = useRoutePayload<WorkbenchRoutePayload>()
  const [repositoryNotificationChannel, setRepositoryNotificationChannel] = useState<string | undefined>(
    repositoryChannel,
  )

  const {disableTargetedEdits} = useTargetedEditsContext()

  const authTokenProvider = useMemo(() => {
    return new SparkAuthTokenProvider(ssoOrganizations.map(org => org.id))
  }, [ssoOrganizations])

  const workbenchData = useWorkbench()
  const {submitPrompt, isMobileSidebarOpen, setIsMobileSidebarOpen, createRepository, friendlyName} = workbenchData

  const handleSidePanelCollapseFromPanel = useCallback(
    (_reason: 'escape') => {
      setIsMobileSidebarOpen(false)
      toggleSidePanel(false)
      focusSidePanelToggleButton()
    },
    [setIsMobileSidebarOpen, toggleSidePanel],
  )

  const handleMobileSidebarClose = useCallback(
    (gesture: 'close-button' | 'escape') => {
      setIsMobileSidebarOpen(false)
      toggleSidePanel(false)

      if (gesture === 'escape') {
        focusSidePanelToggleButton()
      }
    },
    [setIsMobileSidebarOpen, toggleSidePanel],
  )

  useEffect(() => {
    if (!isNewFilePage) {
      removeQueryParam(initialPathQueryParam)
    }
  }, [isNewFilePage])

  const {selectedElement} = useTargetedEditsContext()
  const {width: viewportWidth} = useViewport()

  useEffect(() => {
    // If the viewport resizes smaller than the large breakpoint (1012), we can't show the split view
    if (viewportWidth && viewportWidth < 1012 && workingMode === 'split') {
      setWorkingMode('preview')
    }
  }, [setWorkingMode, viewportWidth, workingMode])

  const pageVisibility = usePageVisibility()
  useEffect(() => {
    const durationMs = pageVisibility.previousStateDurationMs
    const stateName = pageVisibility.state === 'visible' ? 'active' : 'inactive'
    const previousStateName = stateName === 'active' ? 'inactivity' : 'activity'

    workbenchConsole.log(`page became ${pageVisibility.state} after ${durationMs.toFixed(2)}ms of ${previousStateName}`)

    // note! page visibility state name and session ID are part of the global
    //       telemetry metadata, so we don't need to duplicate them here
    sendEvent('workbench.page-visibility-change', {
      previous_state_duration_ms: durationMs,
    })
    // the `sendEvent` function can change frequently, but should not be a dependency
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pageVisibility.state, pageVisibility.previousStateDurationMs])

  const handleCreateRepositoryClose = useCallback(() => {
    setCreateRepositoryModelOpen(false)
  }, [setCreateRepositoryModelOpen])

  const handleTargetedEditsPromptSubmit = (prompt: string, location: NonNullable<ElementPayload['location']>) => {
    submitPrompt(prompt, 'refine', 'targeted_prompt', {
      attachments: {
        locations: [
          {
            filePath: location.start.filePath,
            startLine: location.start.line,
            startColumn: location.start.column,
            endLine: location.end.line,
            endColumn: location.end.column,
          },
        ],
      },
    })
    disableTargetedEdits()
    setSelectedPanel('iterate')
  }

  const subscribeToRepositoryNotifications = useCallback(
    async (attempts = 0) => {
      const maxAttempts = 3
      if (attempts >= maxAttempts) {
        return
      }
      if (!receivesNotificationsFromRepository || repositoryChannel) {
        // If the repository URL is not set, or we're already listening, we don't need to subscribe
        return
      }

      const response = await verifiedFetchJSON(
        `/copilot/spark/workbench/${workbenchData.id}/repository_notifications`,
        {method: 'POST'},
      )
      const result = await response.json()
      if (result.subscribed) {
        setRepositoryNotificationChannel(result.channel)
        return
      } else {
        await new Promise(resolve => setTimeout(resolve, 2000)) // Wait before retrying
        subscribeToRepositoryNotifications(attempts + 1)
      }
    },
    [receivesNotificationsFromRepository, workbenchData, repositoryChannel],
  )

  const handleCreateRepository = useCallback(
    async (repositoryName: string, visibility: RepositoryVisibility) => {
      await createRepository(repositoryName, visibility)
      // Only close the dialog if the feature flag is disabled
      // When enabled, the dialog will manage its own state
      if (!showRepoUrl) {
        setCreateRepositoryModelOpen(false)
      }
      subscribeToRepositoryNotifications()
    },
    [createRepository, setCreateRepositoryModelOpen, subscribeToRepositoryNotifications, showRepoUrl],
  )

  if (!authTokenProvider) return null

  return (
    <PublishingProvider>
      <ErrorsProvider>
        <div id={WORKBENCH_ROOT_ELEMENT_ID} ref={rootRef} data-hpc>
          {isStatusFaviconEnabled && <SparkStatusFavicon />}
          <PageLayout
            containerWidth="full"
            padding="none"
            rowGap="condensed"
            columnGap="none"
            className={styles.pageLayout}
            style={{
              // Account for uncontrollable UI like the staff bar
              '--workspace-editor-offset-top': `${offsetTop}px`,
              // The header height can change if there are banners or if the content wraps
              '--workspace-editor-header-height': `${headerHeight}px`,
            }}
          >
            <PageLayout.Header className="mb-0">
              <Header headerRef={headerRef} />
            </PageLayout.Header>
            <PageLayout.Pane
              position="start"
              aria-label="Side pane"
              className={clsx(styles.pagePane, {[styles.pagePaneExpanded]: sidePanelOpen}, 'd-none d-md-block')}
              width={{
                // 100% is a valid value, but Pane expects {string}px, using workaround until I find better solution
                // @ts-expect-error See above
                default: '100%',
                // @ts-expect-error See above
                min: '100%',
                // @ts-expect-error See above
                max: '100%',
              }}
            >
              <div className={styles.sidePanelWrapper}>
                <SidePanel
                  workbenchData={workbenchData}
                  selectedPanel={selectedPanel}
                  setSelectedPanel={setSelectedPanel}
                  onRequestCollapse={handleSidePanelCollapseFromPanel}
                />
              </div>
            </PageLayout.Pane>

            <PageLayout.Content
              as="div"
              padding="none"
              width="full"
              className={clsx(styles.pageContent, {[styles.contentFullWidth]: !sidePanelOpen})}
            >
              <MainContent copilotCurrentTopic={currentTopic} workbenchData={workbenchData} Editor={Editor} />
            </PageLayout.Content>
          </PageLayout>
          {isMobileSidebarOpen && (
            <Dialog
              title="Edit your spark"
              position={{narrow: 'left', regular: 'left'}}
              height="large"
              width="xlarge"
              className={clsx(styles.sidePanelDialog, 'hide-lg hide-xl height-full')}
              onClose={handleMobileSidebarClose}
            >
              <div className="height-full" style={{minWidth: '332px'}}>
                <SidePanel
                  workbenchData={workbenchData}
                  selectedPanel={selectedPanel}
                  setSelectedPanel={setSelectedPanel}
                  onRequestCollapse={handleSidePanelCollapseFromPanel}
                />
              </div>
            </Dialog>
          )}
          {repositoryNotificationChannel && <RepositoryNotificationHandler channel={repositoryNotificationChannel} />}
          {createRepositoryModelOpen && (
            <CreateRepositoryDialog
              name={friendlyName}
              ownerLogin={createRepoOwner || workbenchData.workbench.billableOwner.login}
              onCancel={handleCreateRepositoryClose}
              onSubmit={handleCreateRepository}
            />
          )}
          {selectedElement && (
            <TargetedEditsInput element={selectedElement} onSubmit={handleTargetedEditsPromptSubmit} />
          )}
        </div>
      </ErrorsProvider>
    </PublishingProvider>
  )
}

try{ Workbench.displayName ||= 'Workbench' } catch {}