import {useWorkspaceEditorUIDispatch} from '@github-ui/workspace-editor/contexts/WorkspaceEditorUIContext'
import {useProvidedRefOrCreate} from '@primer/react'
import {clsx} from 'clsx'
import {useCallback, useEffect, useState} from 'react'

import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useWorkbenchPreview} from '../../contexts/WorkbenchPreviewContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {useCodespaceHelpers} from '../../hooks/use-codespace-helpers'
import workbenchConsole from '../../utilities/console'
import {BannerType} from '../../utilities/workspace-editor-types'
import {SPARK_LIVE_PREVIEW_IFRAME_ID} from './Constants'
import styles from './PreviewArea.module.css'

interface LivePreviewIframeProps {
  show: boolean
  onLoad?: (event: React.SyntheticEvent<HTMLIFrameElement>, empty: boolean) => void
  onError?: (error: Error) => void
}

export function LivePreviewIframe({show, onLoad, onError}: LivePreviewIframeProps) {
  const {refreshPreview, previewBrowserRef} = useWorkbenchUI()
  const {state} = useWorkbenchPreview()
  const [liveUrl, setLiveUrl] = useState<string | null>(null)
  const [livePreviewState, setLivePreviewState] = useState<'inactive' | 'authenticated'>('inactive')
  const ref = useProvidedRefOrCreate(previewBrowserRef)

  const {codespaceData} = useCodespaceContext()
  const codespaceName = codespaceData?.codespaceInfo?.environment_data?.friendlyName
  const {authenticateDevTunnelsPortForwarding} = useCodespaceHelpers()
  const dispatch = useWorkspaceEditorUIDispatch()

  // Effect to reload iframe when Vite WS disconnects
  useEffect(() => {
    if (liveUrl && state.viteServerReady && !state.viteWsConnected) {
      refreshPreview()
    }
  }, [liveUrl, state.viteWsConnected, state.viteServerReady, refreshPreview])

  // Reset live preview authentication when codespace name changes during reconnection
  // ensures authentication is required for the new codespace session
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLiveUrl('')
    setLivePreviewState('inactive')
  }, [codespaceName])

  const authenticate = useCallback(async () => {
    const {authed, url} = await authenticateDevTunnelsPortForwarding('5000', 'live_preview')
    if (!authed) {
      throw new Error('Failed to authenticate dev tunnels port forwarding')
    }

    // Wait a little for the cookies to get set - a safeguard
    await new Promise(resolve => setTimeout(resolve, 200))

    setLiveUrl(url)
  }, [authenticateDevTunnelsPortForwarding])

  useEffect(() => {
    if (!state.viteServerReady || livePreviewState === 'authenticated') {
      return
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    authenticate()
      // eslint-disable-next-line github/no-then
      .then(() => setLivePreviewState('authenticated'))
      // eslint-disable-next-line github/no-then
      .catch(error => {
        workbenchConsole.error('Live Preview authentication failed:', error)
        dispatch({type: 'SET_BANNER', banner: BannerType.PREVIEW_AUTH_FAILED})
        onError?.(error)
      })
  }, [onError, state.viteServerReady, authenticate, dispatch, livePreviewState])

  return (
    <iframe
      id={SPARK_LIVE_PREVIEW_IFRAME_ID}
      ref={ref}
      src={liveUrl ?? ''}
      title="Preview"
      style={{width: '100%', height: '100%', border: 'none'}}
      className={clsx(styles.iframe, show ? styles.iframeVisible : styles.iframeHidden)}
      allow="geolocation; microphone; camera; midi; encrypted-media; clipboard-write; web-share"
      // eslint-disable-next-line @eslint-react/dom/no-unsafe-iframe-sandbox
      sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-popups allow-presentation"
      onLoad={event => onLoad?.(event, !liveUrl)}
    />
  )
}

try{ LivePreviewIframe.displayName ||= 'LivePreviewIframe' } catch {}