import {GitHubAvatar} from '@github-ui/github-avatar'
import {TriangleDownIcon} from '@primer/octicons-react'
import {Button, type ButtonProps, SelectPanel} from '@primer/react'
import {useMemo, useState} from 'react'

import type {UserOrganization} from '../../types/workbench-types'

function alreadySelected(name: string, selection: UserOrganization | undefined) {
  if (!selection) {
    return false
  }
  return selection.name === name
}

interface PublishOrgSelectorProps {
  buttonText?: string
  additionalButtonProps?: Partial<ButtonProps>
  selectOrg: (org: UserOrganization) => void
  removeOrg: (org: UserOrganization) => void
  organizations: UserOrganization[]
  selection: UserOrganization | undefined
  saving: boolean
}

export const PublishOrgSelector = ({
  buttonText,
  additionalButtonProps,
  selection,
  selectOrg,
  removeOrg,
  organizations,
  saving,
}: PublishOrgSelectorProps) => {
  const [open, setOpen] = useState(false)
  const [filter, setFilter] = useState('')

  const filteredOrganizations = useMemo(() => {
    const trimmedFilter = filter.trim().toLowerCase()
    if (!trimmedFilter) {
      return organizations
    }
    return organizations.filter(org => org.name.toLowerCase().includes(trimmedFilter))
  }, [organizations, filter])

  const suggestionItems = useMemo(() => {
    return filteredOrganizations.map(org => ({
      text: org.name,
      id: org.name,
      leadingVisual: () => org.primaryAvatarUrl && <GitHubAvatar alt={org.name} src={org.primaryAvatarUrl} />,
      onAction: () => {
        if (selection && selection.name === org.name) {
          removeOrg(selection)
        } else {
          selectOrg(org)
        }
      },
    }))
  }, [filteredOrganizations, selection, removeOrg, selectOrg])

  const onOpenChange = () => {
    setOpen(!open)
  }

  const onCancel = () => {
    setOpen(false)
  }

  const buttonTextOrDefault = useMemo(() => {
    if (buttonText) {
      return buttonText
    } else if (selection === undefined) {
      return 'Select organization'
    } else {
      return selection.name
    }
  }, [buttonText, selection])

  const selectedOrg = suggestionItems.find(item => alreadySelected(item.id, selection))

  return (
    <SelectPanel
      title="Select organization"
      renderAnchor={({...anchorProps}) => (
        <Button
          loading={saving}
          leadingVisual={
            selection ? () => <GitHubAvatar alt={selection.name} src={selection.primaryAvatarUrl} /> : undefined
          }
          trailingAction={TriangleDownIcon}
          {...additionalButtonProps}
          {...anchorProps}
          aria-haspopup="dialog"
        >
          {buttonTextOrDefault}
        </Button>
      )}
      open={open}
      onOpenChange={onOpenChange}
      onCancel={onCancel}
      items={suggestionItems}
      selected={selectedOrg}
      onSelectedChange={() => {}}
      placeholderText="Filter organizations"
      filterValue={filter}
      onFilterChange={setFilter}
      overlayProps={{
        width: 'medium',
        maxHeight: 'medium',
      }}
    />
  )
}

try{ PublishOrgSelector.displayName ||= 'PublishOrgSelector' } catch {}