import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useMemo} from 'react'

import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {AgentStatus, Service, Status, useGlobalReadOnly, useWorkbenchStore} from '../contexts/WorkbenchStoreContext'

export const ReadOnlyKey = {
  DEFAULT: 'default',
  GENERATE_ACTIONS: 'generate-actions',
  EDITOR: 'editor',
  ITERATION_HISTORY: 'iteration-history',
  CREATE_REPOSITORY: 'create-repository',
  AI_PANEL: 'ai-panel',
  ASSETS_PANEL: 'assets-panel',
  THEME_PANEL: 'theme-panel',
  TARGETED_EDITS: 'targeted-edits',
} as const
export type ReadOnlyKey = (typeof ReadOnlyKey)[keyof typeof ReadOnlyKey]

/**
 * @param {ReadOnlyKey} readOnlyKey The key to determine the read-only state for specific regions/functionalities
 * @returns {boolean}
 * @example
 * useReadOnly(ReadOnlyKey.DEFAULT) // returns true if codespace is disconnected
 * useReadOnly(ReadOnlyKey.EDITOR) // returns true if file syncer is not connected
 * useReadOnly(ReadOnlyKey.GENERATE_ACTIONS) // returns true if agent is generating
 */
export function useReadOnly(readOnlyKey: ReadOnlyKey): boolean {
  const {
    status: {
      [Service.CODESPACE]: codespaceStatus,
      [Service.AGENT]: agentStatus,
      [Service.FILE_SYNCER]: fileSyncerStatus,
      [Service.VITE]: viteStatus,
    },
  } = useWorkbenchStore()
  const [storeReadOnly, _setReadOnly, staticReadOnly, entitlementsQuotaReadOnly] = useGlobalReadOnly()
  const {isFetching} = useWorkbenchContext()

  const agentGenerating = useMemo(
    () =>
      agentStatus === AgentStatus.GENERATING ||
      agentStatus === AgentStatus.WILL_GENERATE ||
      agentStatus === AgentStatus.WILL_GENERATE_INITIAL ||
      isFetching,
    [agentStatus, isFetching],
  )

  if (!isFeatureEnabled('workbench_store_readonly')) {
    return false
  } else if (staticReadOnly) {
    return true
  } else if (!readOnlyKey) {
    throw new Error('readOnlyKey is required')
  }

  switch (readOnlyKey) {
    case ReadOnlyKey.DEFAULT: {
      return storeReadOnly
    }
    case ReadOnlyKey.GENERATE_ACTIONS: {
      return (
        entitlementsQuotaReadOnly ||
        agentGenerating ||
        (codespaceStatus !== Status.CONNECTED && codespaceStatus !== Status.IDLE)
      )
    }
    case ReadOnlyKey.ITERATION_HISTORY:
    case ReadOnlyKey.CREATE_REPOSITORY:
    case ReadOnlyKey.AI_PANEL:
    case ReadOnlyKey.ASSETS_PANEL: {
      return storeReadOnly || fileSyncerStatus !== Status.CONNECTED
    }
    case ReadOnlyKey.EDITOR: {
      return storeReadOnly || fileSyncerStatus !== Status.CONNECTED || agentGenerating
    }
    case ReadOnlyKey.TARGETED_EDITS:
    case ReadOnlyKey.THEME_PANEL: {
      return (
        storeReadOnly || viteStatus !== Status.CONNECTED || fileSyncerStatus !== Status.CONNECTED || agentGenerating
      )
    }
    default: {
      throw new Error(`Unknown readOnlyKey: ${readOnlyKey}`)
    }
  }
}
