import {isFeatureEnabled} from '@github-ui/feature-flags'
import {verifiedFetch, verifiedFetchJSON} from '@github-ui/verified-fetch'
import {createContext, type PropsWithChildren, useCallback, useContext, useEffect, useMemo, useState} from 'react'

import {SPARK_LIVE_PREVIEW_IFRAME_ID} from '../components/PreviewArea/Constants'
import {useIterateAnalytics} from '../telemetry/use-analytics'
import {type KvDeletedPayload, KvEventType, type KvUpdatedPayload} from '../types/kv-event-types'
import {type DataType, parseData} from '../utilities/parse-data'
import {Service, useWorkbenchStore} from './WorkbenchStoreContext'

export interface ParsedTableDataType {
  table: string
  data: DataType
}

export interface DatabaseContextProps {
  runtimePermanentName: string
}

export interface DatabaseContextData {
  fetchAllData: () => Promise<void>
  fetchSpecificKey: (keyName: string) => Promise<void>
  updateKeyInDatabase: (tableName: string, tableData: DataType) => Promise<void>
  deleteKeyFromDatabase: (keyName: string) => Promise<void>
  resetDatabase: () => Promise<void>
  isFetchingData: boolean
  didErrorFetchingData: boolean
  currentData: ParsedTableDataType[]
}

const URLs = {
  allKeys: (runtimePermanentName: string) => `/copilot/spark/runtime/data/${runtimePermanentName}`,
  specificKey: (runtimePermanentName: string, keyName: string, encodeSparkKvKey: boolean) => {
    const encodedKeyName = encodeSparkKvKey ? encodeURIComponent(keyName) : keyName

    return `/copilot/spark/runtime/data/${runtimePermanentName}/${encodedKeyName}`
  },
}

function sendMessageToSpark(message: {type: KvEventType; payload: Record<string, unknown>}) {
  // This function sends a message to the Spark Preview iframe
  // The iframe is expected to be present in the DOM with the ID from PreviewArea.tsx
  const iframe = document.getElementById(SPARK_LIVE_PREVIEW_IFRAME_ID) as HTMLIFrameElement

  if (!iframe || !iframe.contentWindow) {
    // There are many reasons why this iframe might not be present. This is really a best-effort fire-and-forget
    // system, so let's just continue on if things don't work.
    return
  }

  iframe.contentWindow.postMessage(message, '*')
}

export const DatabaseContext = createContext<DatabaseContextData | undefined>(undefined)

export const DatabaseProvider = ({runtimePermanentName, children}: PropsWithChildren<DatabaseContextProps>) => {
  const {onError, onSuccess} = useWorkbenchStore()
  const {iterateStarted, iterateError, iterateSuccess} = useIterateAnalytics('data_panel')

  const encodedSparkKvKeys = isFeatureEnabled('spark_kv_encocoded_keys')

  const [isFetching, setIsFetching] = useState<boolean>(false)
  const [isError, setIsError] = useState<boolean>(false)
  const [currentData, setCurrentData] = useState<ParsedTableDataType[]>([])

  // Private operation to set the value for a key
  const setSpecificKey = (keyName: string, newData: string) => {
    setCurrentData(data => {
      const parsedData = parseData(newData)
      const existingIndex = data?.findIndex(item => item.table === keyName) ?? -1

      if (existingIndex !== -1) {
        // Update existing entry
        return data.map(item => (item.table === keyName ? {...item, data: parsedData} : item))
      } else {
        // Add new entry
        return [...(data || []), {table: keyName, data: parsedData}]
      }
    })
  }

  // Private operation to delete the key from our understanding of the dataset
  const deleteKey = (keyName: string) => {
    setCurrentData(prevData => prevData?.filter(item => item.table !== keyName))
  }

  const fetchSpecificKey = useCallback(
    async (keyName: string) => {
      setIsFetching(true)
      try {
        const response = await verifiedFetch(URLs.specificKey(runtimePermanentName, keyName, encodedSparkKvKeys))
        if (!response.ok) {
          setIsError(true)
          setIsFetching(false)
          return Promise.reject(new Error(`Failed to fetch specific key: response=[${response.status}]`))
        }

        const newData = await response.text()
        setSpecificKey(keyName, newData)

        setIsError(false)
        setIsFetching(false)
      } catch (error) {
        setIsError(true)
        setIsFetching(false)
        return Promise.reject(new Error(`Failed to fetch specific key: ${error}`))
      } finally {
        setIsFetching(false)
      }
    },
    [runtimePermanentName, encodedSparkKvKeys],
  )

  const fetchAllData = useCallback(async () => {
    setIsFetching(true)
    try {
      const response = await verifiedFetchJSON(URLs.allKeys(runtimePermanentName))
      if (!response.ok) {
        setIsFetching(false)
        setIsError(true)
        onError({service: Service.RUNTIME})
        return
      }
      const allKeys = await response.json()
      // Now that we have all keys, we can fetch each key's data
      const results = await Promise.allSettled<ParsedTableDataType>(
        allKeys.map(async (specificKey: string) => {
          const data = await verifiedFetch(URLs.specificKey(runtimePermanentName, specificKey, encodedSparkKvKeys))
          if (!data.ok) {
            return Promise.reject(new Error(`Failed to fetch specific key: response=[${data.status}]`))
          }
          const textData = await data.text()
          return {
            table: specificKey,
            data: parseData(textData),
          }
        }),
      )

      // For now, we're not handling rejected/failed specific key fetches.
      const fetchedData: ParsedTableDataType[] = results
        .filter((result): result is PromiseFulfilledResult<ParsedTableDataType> => result.status === 'fulfilled')
        .map(result => result.value)

      setIsError(false)
      setIsFetching(false)
      onSuccess({service: Service.RUNTIME})
      setCurrentData(fetchedData)
    } catch {
      setIsError(true)
    } finally {
      setIsFetching(false)
    }
  }, [runtimePermanentName, onSuccess, onError, encodedSparkKvKeys])

  const updateKeyInDatabase = useCallback(
    async (tableName: string, tableData: DataType) => {
      const telemetryProperties = iterateStarted()
      try {
        const response = await verifiedFetch(URLs.specificKey(runtimePermanentName, tableName, encodedSparkKvKeys), {
          method: 'POST',
          body: JSON.stringify(tableData.data),
        })

        if (!response.ok) {
          const message = `Failed to update key in database: response=[${response.status}]`
          iterateError(message, response.status, telemetryProperties)
          return Promise.reject(new Error(message))
        }

        iterateSuccess(telemetryProperties)
        sendMessageToSpark({type: KvEventType.SPARK_KV_UPDATED, payload: {key: tableName}})

        setCurrentData(data => {
          return data?.some(item => item.table === tableName)
            ? data?.map(item => (item.table === tableName ? {...item, data: tableData} : item))
            : [...(data || []), {table: tableName, data: tableData}]
        })
      } catch (error) {
        const message = `Failed to update key in database: ${error}`
        iterateError(message, -1, telemetryProperties)
        return Promise.reject(new Error(message))
      }
    },
    [iterateError, iterateStarted, iterateSuccess, runtimePermanentName, encodedSparkKvKeys],
  )

  const deleteKeyFromDatabase = useCallback(
    async (keyName: string) => {
      const telemetryProperties = iterateStarted()
      try {
        const response = await verifiedFetchJSON(URLs.specificKey(runtimePermanentName, keyName, encodedSparkKvKeys), {
          method: 'DELETE',
        })

        if (!response.ok) {
          const message = `Failed to delete key from database: response=[${response.status}]`
          iterateError(message, response.status, telemetryProperties)
          return Promise.reject(new Error(message))
        }

        iterateSuccess(telemetryProperties)
        sendMessageToSpark({type: KvEventType.SPARK_KV_DELETED, payload: {key: keyName}})

        deleteKey(keyName)
      } catch (error) {
        const message = `Failed to delete key from database: ${error}`
        iterateError(message, -1, telemetryProperties)
        return Promise.reject(new Error(message))
      }
    },
    [iterateError, iterateStarted, iterateSuccess, runtimePermanentName, encodedSparkKvKeys],
  )

  const resetDatabase = useCallback(async () => {
    // Iterate over every table key and delete it
    const newData = [...currentData]
    try {
      for (const item of currentData) {
        const response = await verifiedFetchJSON(
          URLs.specificKey(runtimePermanentName, item.table, encodedSparkKvKeys),
          {
            method: 'DELETE',
          },
        )

        if (!response.ok) {
          return Promise.reject(new Error(`Failed to delete key from database: response=[${response.status}]`))
        }

        // Remove the item from the newData array
        newData.splice(
          newData.findIndex(data => data.table === item.table),
          1,
        )
      }
    } catch (error) {
      return Promise.reject(new Error(`Failed to delete key from database: ${error}`))
    } finally {
      setCurrentData(newData)
    }
  }, [currentData, runtimePermanentName, encodedSparkKvKeys])

  // Fetch all data when the provider mounts
  useEffect(() => {
    fetchAllData()
  }, [fetchAllData])

  const handleMessageFromIframe = useCallback(
    async (event: MessageEvent) => {
      switch (event.data?.type) {
        case KvEventType.SPARK_KV_UPDATED: {
          // Inform the DatabaseContext to refetch the specific key.
          const {key, value} = event.data.payload satisfies KvUpdatedPayload
          if (value && typeof value === 'string') {
            setSpecificKey(key, value)
          } else {
            await fetchSpecificKey(key)
          }
          break
        }
        case KvEventType.SPARK_KV_DELETED: {
          const {key} = event.data.payload satisfies KvDeletedPayload
          deleteKey(key)
          break
        }
        default:
          // Do nothing
          break
      }
    },
    [fetchSpecificKey],
  )

  // Handle events from preview
  useEffect(() => {
    window.addEventListener('message', handleMessageFromIframe)

    return () => {
      window.removeEventListener('message', handleMessageFromIframe)
    }
  }, [handleMessageFromIframe])

  const contextValue = useMemo(
    () =>
      ({
        fetchAllData,
        fetchSpecificKey,
        updateKeyInDatabase,
        deleteKeyFromDatabase,
        resetDatabase,
        isFetchingData: isFetching,
        didErrorFetchingData: isError,
        currentData,
      }) satisfies DatabaseContextData,
    [
      fetchAllData,
      fetchSpecificKey,
      updateKeyInDatabase,
      deleteKeyFromDatabase,
      resetDatabase,
      isFetching,
      isError,
      currentData,
    ],
  )

  return <DatabaseContext.Provider value={contextValue}>{children}</DatabaseContext.Provider>
}

export const useDatabaseContext = () => {
  const context = useContext(DatabaseContext)
  if (!context) {
    throw new Error('useDatabaseContext must be used within a DatabaseProvider')
  }
  return context
}

