import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {SPARK_LIVE_PREVIEW_IFRAME_ID} from '../components/PreviewArea/Constants'
import {useCodespaceContext} from '../contexts/CodespaceContext'
import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {useWorkbenchNavigate} from '../hooks/use-workbench-navigate'
import type {WorkbenchRoutePayload} from '../types/workbench-types'
import {
  useGetThemeVariables,
  useModifyFontFamily,
  useModifyGlobalCssVariable,
  useModifyJsxClassName,
  useModifyJsxText,
  useModifyThemeVariables,
} from './query'
import type {BridgeMessage, ElementPayload, HostMessage} from './types'

function sendMessageToHost(message: BridgeMessage) {
  const iframe = document.getElementById(SPARK_LIVE_PREVIEW_IFRAME_ID) as HTMLIFrameElement

  if (!iframe || !iframe.contentWindow) {
    return
  }

  iframe.contentWindow.postMessage(message, '*')
}

/**
 * Hook for managing targeted edits functionality
 * @param announce - Function to announce messages to screen readers
 */
export function useTargetedEdits(announce: (message: string) => void) {
  const payload = useRoutePayload<WorkbenchRoutePayload>()
  const {sparkFileUrl, isFetching} = useWorkbenchContext()

  const {codespaceData} = useCodespaceContext()

  const {friendlyName} = codespaceData.codespaceInfo?.environment_data || {}
  const domain = codespaceData.remoteProvider?.tunnelProps.domain ?? 'app.github.dev'

  const designerServerUrl = useMemo(() => {
    if (!friendlyName || !domain) return ''
    return `https://${friendlyName}-4000.${domain}`
  }, [friendlyName, domain])

  const tunnelToken =
    codespaceData.codespaceInfo?.environment_data.connection.tunnelProperties?.connectAccessToken || ''

  const [isEnabled, setIsEnabled] = useState(false)
  const [selectedElement, setSelectedElement] = useState<ElementPayload | null>(null)
  const prevElement = useRef<ElementPayload | null>(null)
  const lastFocusedButtonLoc = useRef<string | null>(null)
  const inputRef = useRef<HTMLInputElement | null>(null)
  const selectButtonRef = useRef<HTMLButtonElement | null>(null)
  const themePanelRef = useRef<HTMLElement | null>(null)

  const editMethod = isEnabled ? 'targeted_sidebar' : 'theme_panel'
  const {mutateAsync: modifyJsxClassName} = useModifyJsxClassName(designerServerUrl, tunnelToken, editMethod)
  const {mutateAsync: modifyJsxText} = useModifyJsxText(designerServerUrl, tunnelToken, editMethod)
  const {mutateAsync: modifyGlobalCssVariable} = useModifyGlobalCssVariable(designerServerUrl, tunnelToken, editMethod)
  const {mutateAsync: modifyThemeVariables} = useModifyThemeVariables(designerServerUrl, tunnelToken, editMethod)
  const {mutateAsync: modifyFontFamily} = useModifyFontFamily(designerServerUrl, tunnelToken)

  const {data: themeVariables, refetch: refetchThemeVariables} = useGetThemeVariables(designerServerUrl, tunnelToken)

  const navigate = useWorkbenchNavigate()

  const enableTargetedEdits = useCallback(async () => {
    setIsEnabled(true)
    sendMessageToHost({
      type: 'spark:designer:bridge:enable',
    })

    // Announce instructions to screen reader users
    announce(
      'Element selector mode enabled. Use Tab to navigate between elements, Shift+Enter to cycle edit modes, or Escape to exit selector mode.',
    )
  }, [announce])

  const disableTargetedEdits = useCallback(() => {
    setIsEnabled(false)
    setSelectedElement(null)
    sendMessageToHost({
      type: 'spark:designer:bridge:disable',
    })

    // Focus the "Select element to edit" button when exiting selector mode
    // This is especially important when user presses Escape while tabbing through elements
    if (selectButtonRef.current) {
      selectButtonRef.current.focus()
    }
  }, [])

  useEffect(() => {
    const handler = (event: MessageEvent<HostMessage>) => {
      // TODO: check origin of the event
      // if (event.origin !== designerServerUrl) return

      switch (event.data.type) {
        case 'spark:designer:host:element:selected': {
          setSelectedElement(event.data.element)
          const {location, component} = event.data.element
          const path = location?.start.filePath ?? component.location?.start.filePath

          if (path) {
            navigate(path)
          }
          return
        }
        case 'spark:designer:bridge:element:updated': {
          const updatedElement = event.data.element
          setSelectedElement((prev: ElementPayload | null) => {
            if (prev) {
              return updatedElement
            }
            return prev
          })
          return
        }

        case 'spark:designer:bridge:element:deselected': {
          setSelectedElement(null)
          return
        }

        case 'spark:designer:host:focus-input-requested': {
          const {buttonDataLoc} = event.data
          lastFocusedButtonLoc.current = buttonDataLoc

          // Focus the targeted edits input
          if (inputRef.current) {
            inputRef.current.focus()
          }
          return
        }

        case 'spark:designer:host:disable-requested': {
          // User pressed Escape while tabbing through elements - disable selector mode
          disableTargetedEdits()
          return
        }
      }
    }

    window.addEventListener('message', handler)
    return () => {
      window.removeEventListener('message', handler)
    }
  }, [designerServerUrl, tunnelToken, navigate, payload.workbench.id, sparkFileUrl, disableTargetedEdits, isEnabled])

  const toggleTargetedEdits = useCallback(() => {
    if (isEnabled) {
      disableTargetedEdits()
    } else {
      enableTargetedEdits()
    }
  }, [isEnabled, disableTargetedEdits, enableTargetedEdits])

  useEffect(() => {
    if (isFetching) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      disableTargetedEdits()
    }
  }, [isFetching, disableTargetedEdits])

  useEffect(() => {
    if (!selectedElement) return

    if (selectedElement.text !== null && selectedElement.text !== prevElement.current?.text) {
      const location = selectedElement.location ?? selectedElement.component.location!
      modifyJsxText({
        filePath: location.start.filePath,
        line: location.start.line,
        column: location.start.column,
        content: selectedElement.text,
      })
    }

    prevElement.current = selectedElement
  }, [modifyJsxText, selectedElement])

  return useMemo(
    () => ({
      targetedEditsEnabled: isEnabled,
      disableTargetedEdits,
      toggleTargetedEdits,
      selectedElement,
      modifyJsxClassName,
      modifyJsxText,
      modifyGlobalCssVariable,
      modifyThemeVariables,
      modifyFontFamily,
      themeVariables,
      refetchThemeVariables,
      inputRef,
      lastFocusedButtonLoc,
      selectButtonRef,
      themePanelRef,
    }),
    [
      isEnabled,
      selectedElement,
      disableTargetedEdits,
      toggleTargetedEdits,
      modifyJsxClassName,
      modifyJsxText,
      modifyGlobalCssVariable,
      modifyThemeVariables,
      modifyFontFamily,
      themeVariables,
      refetchThemeVariables,
    ],
  )
}
