import {getOS} from '@github-ui/get-os'

export interface SafariVersion {
  isSafari: true
  major: number
  minor: number
  /**
   * Whether the current device is running on the iOS platform.
   */
  isIos: boolean
}

export interface NotSafari {
  isSafari: false

  /**
   * Whether the current device is running on the iOS platform.
   */
  isIos: boolean
}

export type BrowserVersion = SafariVersion | NotSafari

export function getBrowserVersion(): BrowserVersion {
  const ua = navigator.userAgent
  const versionMatch = ua.match(/Version\/(\d+)\.(\d+)/)

  const {isIOS} = getOS()
  const isSafari = isIOS ? isIosSafari() : /^((?!chrome|android).)*safari/i.test(ua)

  if (isSafari && versionMatch) {
    const major = parseInt(versionMatch[1] ?? '0', 10)
    const minor = parseInt(versionMatch[2] ?? '0', 10)
    return {
      isSafari,
      major,
      minor,
      isIos: isIOS,
    }
  }

  return {
    isSafari: false,
    isIos: isIOS,
  } // Not Safari or version unknown
}

export function isSafariTooOldForCHIPS(browserVersion: BrowserVersion): boolean {
  return (
    browserVersion.isSafari && (browserVersion.major < 18 || (browserVersion.major === 18 && browserVersion.minor < 4))
  )
}

export function isProblematicSafariVersion(browserVersion: BrowserVersion): boolean {
  if (browserVersion.isSafari === false) {
    return browserVersion.isIos // on iOS all browsers besides Safari are affected
  }

  // CHIPS supported in Safari 18.4 at this point only
  // Less than that didn't have the support at all
  // 18.5 rolled it back because of bugs https://bugs.webkit.org/show_bug.cgi?id=292975

  if (isSafariTooOldForCHIPS(browserVersion)) {
    return true
  }

  // we treat any version after 18.4 as problematic, until the bugs are resolved
  // related issue: https://github.com/github/spark/issues/1798
  const isEighteenFivePlus = browserVersion.major === 18 && browserVersion.minor >= 5
  return isEighteenFivePlus || browserVersion.major >= 19
}

/**
 * Check if the current browser is the Safari on iOS itself, and not
 * a wrapper like Chrome, Firefox, Edge, etc.
 *
 * Note! should be used only on `iOS` platform (e.g., with {@link isIOS} function),
 *       otherwise will yield incorrect results!
 */
export function isIosSafari(): boolean {
  const ua = navigator.userAgent

  return /Safari/.test(ua) && !/CriOS|FxiOS|EdgiOS|OPiOS|DuckDuckGo|Brave/.test(ua)
}
