// eslint-disable-next-line no-restricted-imports
import {ScreenSize, useScreenSize} from '@github-ui/screen-size'
import {ActionList, IconButton} from '@primer/react'
import {clsx} from 'clsx'
import {memo, useCallback, useMemo} from 'react'

import {strings} from '../../constants'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useTargetedEditsContext} from '../../contexts/TargetedEditsContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'
import {TargetIcon} from '../CustomIcons'
import styles from './Header.module.css'

export const SelectTargetEdit = memo(function SelectTargetEditButton({
  className,
  variant,
}: {
  className?: string
  variant: 'menu' | 'icon'
}) {
  const {isFetching} = useWorkbenchContext()
  const {toggleSidePanel, workingMode} = useWorkbenchUI()
  const {toggleTargetedEdits, targetedEditsEnabled, selectButtonRef} = useTargetedEditsContext()
  const readOnlyTargetedEdits = useReadOnly(ReadOnlyKey.TARGETED_EDITS)
  const {screenSize} = useScreenSize()
  const {codespaceData} = useCodespaceContext()

  const isLargeScreen = screenSize >= ScreenSize.large
  const isReady = codespaceData?.codespaceState === 'ready'
  const isAbleToTargetEdit = isReady && !isFetching && !readOnlyTargetedEdits && workingMode !== 'code'

  const handleTargetedEditsClick = useCallback(() => {
    if (!targetedEditsEnabled) {
      toggleSidePanel(true)
    }
    toggleTargetedEdits()
  }, [targetedEditsEnabled, toggleSidePanel, toggleTargetedEdits])

  const inactiveDescription = useMemo(() => {
    if (workingMode === 'code') return strings.ACTION_UNAVAILABLE_MODE
    if (isFetching) return strings.ACTION_UNAVAILABLE_ITERATION
    if (!isAbleToTargetEdit) return strings.ACTION_UNAVAILABLE
    return undefined
  }, [workingMode, isFetching, isAbleToTargetEdit])

  return variant === 'menu' ? (
    <ActionList.Item
      aria-label="Select element to edit"
      className={clsx(styles.targetedEditsButton, className)}
      hidden={isLargeScreen}
      onSelect={toggleTargetedEdits}
      inactiveText={inactiveDescription}
    >
      <ActionList.LeadingVisual>
        <TargetIcon />
      </ActionList.LeadingVisual>
      Select an element
    </ActionList.Item>
  ) : (
    <IconButton
      ref={selectButtonRef}
      icon={TargetIcon}
      aria-label="Select element to edit"
      onClick={() => {
        if (!isAbleToTargetEdit) return
        handleTargetedEditsClick()
      }}
      className={clsx(
        styles.targetedEditsButton,
        {[styles.toggledButton]: targetedEditsEnabled},
        'hide-sm hide-md',
        className,
      )}
      inactive={!isAbleToTargetEdit}
      description={inactiveDescription}
    />
  )
})

try{ SelectTargetEdit.displayName ||= 'SelectTargetEdit' } catch {}