import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {PaperAirplaneIcon} from '@primer/octicons-react'
import {Banner, IconButton, Stack, Textarea} from '@primer/react'
import {useCallback, useRef} from 'react'

import {PROMPT_PLACEHOLDER} from '../utils/constants'
import {LegalDisclaimer} from './LegalDisclaimer'
import {MAX_HEIGHT, MIN_HEIGHT} from './PromptArea'
import styles from './PromptArea.module.css'

const DisabledPromptArea: React.FC = () => {
  const promptInputRef = useRef<HTMLTextAreaElement>(null)
  const textAreaScrollContainer = useRef<HTMLDivElement>(null)

  const adjustHeight = useCallback(() => {
    if (!promptInputRef.current || !textAreaScrollContainer.current) return

    const currentScrollPosition = textAreaScrollContainer.current.scrollTop

    promptInputRef.current.style.height = '0'
    const scrollHeight = promptInputRef.current.scrollHeight
    const containerHeight = Math.min(Math.max(scrollHeight, MIN_HEIGHT), MAX_HEIGHT)

    // This 48px corresponds to --form-container-actions-height in CSS
    promptInputRef.current.style.height = `${containerHeight - 48}px`
    textAreaScrollContainer.current.style.height = `${containerHeight}px`
    textAreaScrollContainer.current.scrollTop = currentScrollPosition
  }, [promptInputRef, textAreaScrollContainer])

  useLayoutEffect(() => {
    adjustHeight()
  }, [adjustHeight])

  return (
    <form className={styles.formContainer}>
      <div className={styles.accessDisabledContainer}>
        <Banner
          aria-label="Spark access is disabled."
          title="Spark access is disabled."
          hideTitle
          description="Spark access has been disabled by the admin of your organization or enterprise."
        />
        <div>
          <Textarea
            autoFocus
            className={styles.disabledPromptInputContainer}
            placeholder={PROMPT_PLACEHOLDER}
            ref={promptInputRef}
            resize="none"
            disabled
          />
          <div className={styles.disabledFormContainerActions}>
            <IconButton
              icon={PaperAirplaneIcon}
              aria-label="Submit prompt"
              data-testid="submit-prompt"
              tooltipDirection="n"
              variant="invisible"
              inactive
              aria-disabled
            />
          </div>
        </div>
      </div>
    </form>
  )
}

export const AccessDisabled = () => {
  return (
    <>
      <DisabledPromptArea />
      <Stack
        direction={{narrow: 'vertical', regular: 'horizontal', wide: 'horizontal'}}
        wrap="wrap"
        gap={{narrow: 'normal', regular: 'condensed', wide: 'condensed'}}
        align={{narrow: 'stretch', regular: 'center', wide: 'center'}}
      >
        <LegalDisclaimer />
      </Stack>
    </>
  )
}

try{ DisabledPromptArea.displayName ||= 'DisabledPromptArea' } catch {}
try{ AccessDisabled.displayName ||= 'AccessDisabled' } catch {}