interface PdfPreviewProps {
  src: string
  className?: string
  onDownload?: () => void
}

export function PdfPreview({src, className, onDownload}: PdfPreviewProps) {
  // Accept both data URLs and blob URLs for PDF preview
  const isValidPdfSrc = src && (src.startsWith('data:application/pdf') || src.startsWith('blob:'))

  if (!isValidPdfSrc) {
    return (
      <div className="d-flex flex-column flex-justify-center flex-items-center height-full p-4">
        <p className="mb-2">Unable to preview PDF</p>
        {onDownload && (
          <button type="button" className="btn btn-primary" onClick={onDownload}>
            Download PDF
          </button>
        )}
      </div>
    )
  }

  return (
    <div className="d-flex flex-justify-center flex-items-center height-full p-4">
      <object
        data={src}
        type="application/pdf"
        className={`width-full height-full border-0 rounded-1 ${className || ''}`}
        title="PDF Viewer"
      >
        <div className="d-flex flex-column flex-justify-center flex-items-center height-full p-4">
          <p className="mb-2">Your browser does not support embedded PDFs.</p>
          {onDownload ? (
            <button type="button" className="btn btn-primary" onClick={onDownload}>
              Download PDF
            </button>
          ) : (
            <a href={src} download className="btn btn-primary">
              Download PDF
            </a>
          )}
        </div>
      </object>
    </div>
  )
}

try{ PdfPreview.displayName ||= 'PdfPreview' } catch {}