import {clsx} from 'clsx'
import {useEffect, useRef, useState} from 'react'

import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useFileSyncerContext} from '../../contexts/FileSyncerContext'
import {useIterationHistory} from '../../contexts/IterationHistoryContext'
import {useServerEvents} from '../../contexts/ServerEventsContext'
import {codespaceInfoForTelemetry, useCodespaceHelpers} from '../../hooks/use-codespace-helpers'
import {useAnalytics} from '../../telemetry/use-analytics'
import workbenchConsole from '../../utilities/console'
import {SPARK_STATIC_PREVIEW_IFRAME_ID, STATIC_PREVIEW_PORT} from './Constants'
import styles from './PreviewArea.module.css'

interface StaticPreviewIframeProps {
  show: boolean
  onLoad?: (event: React.SyntheticEvent<HTMLIFrameElement>, empty: boolean) => void
  onError?: (error: Error) => void
  isFetching: boolean
  onPreviewAvailableChange?: (available: boolean) => void
  onReady?: () => void
}

export function StaticPreviewIframe({
  show,
  onLoad,
  isFetching,
  onPreviewAvailableChange,
  onReady,
}: StaticPreviewIframeProps) {
  const sendEvent = useAnalytics()
  const {authenticateDevTunnelsPortForwarding} = useCodespaceHelpers()
  const {codespaceData} = useCodespaceContext()
  const {isInitialIteration} = useIterationHistory()
  const {agentLifeCycle} = useServerEvents()
  const codespaceName = codespaceData?.codespaceInfo?.environment_data.friendlyName
  const [staticPreviewUrl, setStaticPreviewUrl] = useState<string | null>(null)
  const [staticPreviewState, setStaticPreviewState] = useState<'inactive' | 'built' | 'running' | 'authenticated'>(
    'inactive',
  )
  const staticPreviewStartTimeRef = useRef<number | null>(null)
  const staticPreviewBuildInProgressRef = useRef<boolean>(false)
  const {getFileSyncerV2, fileSyncerStarted, syncerMode} = useFileSyncerContext()

  // Effect to build the app for static preview
  useEffect(() => {
    if (!isFetching) return
    if (codespaceData.codespaceState !== 'ready') return
    if (staticPreviewState !== 'inactive') return
    if (isInitialIteration) return // don't show static preview during initial prompt submission
    if (syncerMode !== 'codespace' || !fileSyncerStarted) return // cant build static preview without file syncer
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) return // no file syncer available
    if (staticPreviewBuildInProgressRef.current) return // prevent concurrent builds
    staticPreviewBuildInProgressRef.current = true
    setStaticPreviewUrl(null)

    // Build by calling fileSyncer.buildStaticPreview() if it is available
    const buildStaticPreview = async () => {
      const buildStartTime = performance.now()

      // Set the overall static preview start time
      staticPreviewStartTimeRef.current = buildStartTime

      sendEvent('preview.static.build.start', {
        timestamp: new Date().toISOString(),
        v2: true,
        ...codespaceInfoForTelemetry(codespaceData),
      })

      try {
        await fileSyncer.buildStaticPreview()
        setStaticPreviewState('built')
        onPreviewAvailableChange?.(true)

        sendEvent('preview.static.build.success', {
          timestamp: new Date().toISOString(),
          v2: true,
          duration: performance.now() - buildStartTime,
          ...codespaceInfoForTelemetry(codespaceData),
        })
      } catch (error) {
        workbenchConsole.error('Failed to build static preview:', error)
        setStaticPreviewState('inactive')
        onPreviewAvailableChange?.(false)

        sendEvent('preview.static.build.error', {
          timestamp: new Date().toISOString(),
          duration: performance.now() - buildStartTime,
          v2: true,
          error: error instanceof Error ? error.message : String(error),
          ...codespaceInfoForTelemetry(codespaceData),
        })
      } finally {
        staticPreviewBuildInProgressRef.current = false
      }
    }

    buildStaticPreview()
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    codespaceData,
    isFetching,
    isInitialIteration,
    staticPreviewState,
    getFileSyncerV2,
    syncerMode,
    fileSyncerStarted,
  ])

  // Effect to watch for static preview server state
  useEffect(() => {
    if (!isFetching) return
    if (codespaceData.codespaceState !== 'ready') return
    if (staticPreviewState !== 'built') return

    let pollInterval: number | null = null
    let timeoutId: NodeJS.Timeout | null = null
    const pollStartTime = performance.now()

    sendEvent('preview.static.server.poll.start', {
      timestamp: new Date().toISOString(),
      v2: true,
      ...codespaceInfoForTelemetry(codespaceData),
    })

    // Poll for static preview state and set staticPreviewState to 'running' if it is running
    const checkStaticPreviewServer = async () => {
      try {
        const tunnelProps = codespaceData?.remoteProvider?.tunnelProps
        const domain = tunnelProps?.domain ?? 'app.github.dev'
        const accessToken = tunnelProps?.connectAccessToken

        if (!accessToken || !codespaceName) return {authed: false, url: ''}

        const url = `https://${codespaceName}-${STATIC_PREVIEW_PORT}.${domain}/`
        const headers = new Headers()
        headers.set('X-Tunnel-Authorization', `tunnel ${accessToken}`)

        const response = await fetch(url, {
          signal: AbortSignal.timeout(500),
          headers,
        })

        if (response.ok) {
          if (pollInterval) window.clearInterval(pollInterval)
          if (timeoutId) clearTimeout(timeoutId)
          setStaticPreviewState('running')
          onPreviewAvailableChange?.(true)

          sendEvent('preview.static.server.poll.success', {
            timestamp: new Date().toISOString(),
            duration: performance.now() - pollStartTime,
            v2: true,
            ...codespaceInfoForTelemetry(codespaceData),
          })
        }
      } catch {
        // NOOP
      }
    }

    checkStaticPreviewServer()
    pollInterval = window.setInterval(checkStaticPreviewServer, 500)
    timeoutId = setTimeout(() => {
      if (staticPreviewState === 'built') {
        // If the static preview server is still not running (stays in built) after 10 seconds, stop attempting
        if (pollInterval) window.clearInterval(pollInterval)
        setStaticPreviewState('inactive')
        onPreviewAvailableChange?.(false)

        sendEvent('preview.static.server.poll.timeout', {
          timestamp: new Date().toISOString(),
          duration: performance.now() - pollStartTime,
          timeoutMs: 10000,
          v2: true,
          ...codespaceInfoForTelemetry(codespaceData),
        })
      }
    }, 10000)

    return () => {
      if (pollInterval) {
        clearInterval(pollInterval)
      }

      if (timeoutId) {
        clearTimeout(timeoutId)
      }
    }
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    codespaceData,
    codespaceData.codespaceState,
    codespaceData?.remoteProvider?.tunnelProps,
    codespaceName,
    isFetching,
    isInitialIteration,
    staticPreviewState,
  ])

  // Effect to deactivate the static preview server when not fetching
  useEffect(() => {
    if (isFetching) return

    if (staticPreviewState === 'inactive') return

    sendEvent('preview.static.deactivate', {
      timestamp: new Date().toISOString(),
      staticPreviewState,
      v2: true,
      ...codespaceInfoForTelemetry(codespaceData),
    })

    setStaticPreviewState('inactive')
    onPreviewAvailableChange?.(true)
    setStaticPreviewUrl(null)
    staticPreviewStartTimeRef.current = null
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [codespaceData, isFetching, staticPreviewState, onPreviewAvailableChange])

  // Effect to authenticate the static preview url when the server is running
  useEffect(() => {
    if (!isFetching) return
    if (codespaceData.codespaceState !== 'ready') return
    if (staticPreviewState !== 'running') return

    let timeoutId: NodeJS.Timeout | null = null
    async function authenticateStaticPreview() {
      const authStartTime = performance.now()

      sendEvent('preview.static.auth.start', {
        timestamp: new Date().toISOString(),
        v2: true,
        ...codespaceInfoForTelemetry(codespaceData),
      })

      const {authed, url} = await authenticateDevTunnelsPortForwarding(STATIC_PREVIEW_PORT, 'static_preview')
      if (!authed) {
        workbenchConsole.error('Failed to authenticate static preview')
        setStaticPreviewState('inactive')
        onPreviewAvailableChange?.(false)
        sendEvent('preview.static.auth.error', {
          timestamp: new Date().toISOString(),
          duration: performance.now() - authStartTime,
          v2: true,
          ...codespaceInfoForTelemetry(codespaceData),
        })
        return
      }
      // Wait a little for the cookies to get set - a safeguard
      await new Promise(resolve => {
        timeoutId = setTimeout(resolve, 200)
      })

      if (!isFetching) return

      setStaticPreviewUrl(url)
      setStaticPreviewState('authenticated')
      // Don't call onReady if agent requested to show the preview
      if (agentLifeCycle !== 'showPreviewRequested') {
        onReady?.()
      }

      sendEvent('preview.static.auth.success', {
        timestamp: new Date().toISOString(),
        duration: performance.now() - authStartTime,
        v2: true,
        ...codespaceInfoForTelemetry(codespaceData),
      })

      sendEvent('preview.static.activated', {
        timestamp: new Date().toISOString(),
        staticPreviewUrl: url,
        v2: true,
        totalDuration: staticPreviewStartTimeRef.current ? performance.now() - staticPreviewStartTimeRef.current : null,
        ...codespaceInfoForTelemetry(codespaceData),
      })
    }

    authenticateStaticPreview()

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId)
      }
    }
    // the `sendEvent()` function always changes so we don't want to include it into the dependencies list
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    authenticateDevTunnelsPortForwarding,
    codespaceData,
    codespaceData.codespaceState,
    isFetching,
    staticPreviewState,
    onReady,
    onPreviewAvailableChange,
    agentLifeCycle,
  ])

  // Reset static preview authentication when codespace name changes during reconnection
  // ensures authentication is required for the new codespace session
  useEffect(() => {
    setStaticPreviewUrl('')
    setStaticPreviewState('inactive')
  }, [codespaceName])

  return (
    <iframe
      id={SPARK_STATIC_PREVIEW_IFRAME_ID}
      src={staticPreviewUrl ?? ''}
      title="Preview"
      style={{width: '100%', height: '100%', border: 'none'}}
      className={clsx(styles.iframe, show ? styles.iframeVisible : styles.iframeHidden)}
      allow="geolocation; microphone; camera; midi; encrypted-media; clipboard-write; web-share"
      // eslint-disable-next-line @eslint-react/dom/no-unsafe-iframe-sandbox
      sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-popups allow-presentation"
      onLoad={event => onLoad?.(event, !staticPreviewUrl)}
    />
  )
}

try{ StaticPreviewIframe.displayName ||= 'StaticPreviewIframe' } catch {}